        "summary": "李肖娜，现任连云港市海州区新海街道海连社区党委书记、居委会主任。海连社区为老城区，人口近年陡增且人员来源广，治理挑战大。她带领社区学总书记基层治理论述，探索“邻里党建”，引导群众“与邻为善、以邻为伴”，推动党群从相识到相助，社区获评“全国民主法治示范社区”，重点做三件事：​\n一是组织扎根邻里。按小区划5个网格并建党支部，健全“社区党委—网格党支部—党员中心户”架构；每小区设党群服务站，“两委”成员驻点办公；街道设综合执法站，19家单位党建联建，聘7名快递员任兼职网格员。\n二是矛盾化解邻里。深化“红色物业”，设立社区与物业共用服务台，5名党员任物业项目经理并兼社区委员；网格党支部月开1次议事会，解300余件疑难事；依托“云望新海”平台，对重点人群标签化管理、重点区域智能监测。\n三是服务落实邻里。聚焦“一老一幼”，设老年学院、托管等项目，开瑜伽等课程，打造“海好有你”文化；“公益+市场”开办中医理疗、社区食堂（运行2年，日接待300余人）；每周义诊、定期讲座，办邻里节（700余人参与）等活动，党群服务中心成“邻里中心”。",
