        "summary": "段金梅，女，1977年9月生，中共党员，大学学历，社会工作师，现任泰州市海陵区城东街道东城社区党总支书记、居委会主任。2007年9月参加社区工作，2020年12月任现职，深耕社区15年，获“全国优秀城乡社区工作者”“泰州市三八红旗手”等荣誉，带领社区获全国综合减灾示范社区等称号。​\n她心系困难群众，将150余名困难群众记挂在心：为残疾儿童多次上门协调办理残疾证，冒雨换灯泡、陪家属就医；做失独家庭“好女儿”、困境儿童“主任妈妈”，用“五心”为居民办实事。​\n疫情期间，她术后未愈便瞒着子女冲在一线，参与售口罩、入户摸排、给隔离户送菜等工作，以“舍小家为大家”的担当凝聚抗疫力量，感染身边人。​\n她创新治理模式，探索“一核三精五联”工作法：以党建为核心，精准识需求、联资源、供帮扶，借“五社联动”提升服务能力，推动社区服务与社会组织融合，显著增强居民获得感、幸福感、安全感。​",
