        "summary": "黄晓慧，女，1979年7月生，中共党员，本科，助理社会工作师，现任泰州市姜堰区罗塘街道中天社区党委书记、居委会主任。2010年8月起先后在4个社区工作，2022年获评“全国优秀城乡社区工作者”，还曾获泰州市“巾帼建功”标兵等荣誉，2020年10月任职中天社区后，带领社区获“全国示范性老年友好型社区”“江苏省文明社区”称号。​\n中天社区是2848户1万多人的保障型社区，人员复杂。黄晓慧带领团队探索“三亲”治理模式：一是建社区智慧平台，组织党员网上认“微心愿”，提供“定制化服务”，已办为民服务100多项、实事10多项；二是建50个微网格，借微信群等建快速反应、巡查、调处机制，化解纠纷300多起，还延伸至疫情防控；三是优化睦邻平台，为高龄老人等提供“助家政”服务，为残疾人创设“创翼之家”和“一对一”工疗项目，2021年帮助8名残障人士就业、60名残疾人家属就近就业，相关服务品牌获评泰州“十佳”，项目入选省优秀案例。",
