        "summary": "骆婷，女，48岁，现任徐州市鼓楼区鼓楼花园社区党委书记、居委会主任，2003年6月参加工作，曾作为典型代表在江苏省建党99周年事迹报告会发言，获江苏省委书记接见，先后获“全国抗击新冠肺炎疫情先进个人”“全国优秀共产党员”“江苏省三八红旗手”等荣誉。​\n疫情防控中，她第一时间部署防控，号召党员“向党旗报到”，带动200名群众志愿加入，组建5个工作组，逐户排查，摸排出重点地区返徐及密接人员100余人，居家隔离56户，实现“联防联控无死角”。\n社区治理上，她依托网格化体系，建“凝心工作室”“骆婷党代表工作室”，化解纠纷190余起；推“1+N”党员联户机制，解决“飞线充电”等问题；实行“党建统领红物业”，提升服务质量。​\n惠民实事方面，她2023年底协调整治小区易淹点，新建排涝泵站及雨污水管网，2024年9月完工；带领社区完成3次老旧小区改造，增设车位、健身设施；作为徐州首批垃圾分类试点，推动居民养成分类习惯，还打造“15分钟生活圈”，满足居民就医、养老等需求。​",
