        "summary": "陆众山，男，1982年10月生，中共党员，本科，现任盐都区潘黄街道宝才社区党总支书记、居委会主任。2011年6月参加社区工作，曾在盐龙街道社保中心等单位任职，2020年12月任现职，2021年获江苏省统计局人口普查先进个人，2022年11月获评“全国优秀城乡社区工作者”。\n他深耕社区10余年，创新治理显成效。推动产城融合，推进工业园区企业转型升级，2021年创建国家级充分就业示范社区；创新“六三一”工作法，以“六大员”系民情、“三知道”纾民生、“一跟进”解民困，开展文明活动提升居民素质，牵头整治老旧小区，新建2000平方米党群服务中心，设1个服务站、2个服务点及10个社会组织。​\n他俯身为民，暖情服务赢民心。提“五民工程、五心家园”目标，设“零距离联系卡”；帮困难居民蔡银生协调保洁岗位，为小区安装19个单元无障碍通道；“以疏代堵”设晾晒点、增停车位；疫情期间组党员防卫队守一线；通过“一奖三免六补助”，每年惠及居民350万元，获群众赞誉。",
