        "summary": "谈国琴‌，女，1967年12月出生，1992年12月入党，现任湖州市吴兴区龙泉街道党委委员、白鱼潭社区党委书记。谈国琴自2000年下岗后，于2001年参加湖州市社区干部公开竞聘，成为社区干部‌。\n谈国琴在社区工作中表现出色，她倡导成立了多个居民自治组织，如关心下一代协会、志愿者协会、文体协会、老年协会等，极大地丰富了居民的业余文化生活‌。她以真诚和耐心处理社区事务，被誉为“调解专家”，社区矛盾纠纷调处率达到100%，调处成功率在97%以上‌。谈国琴特别关注社区的老弱病残、低保户和低收入群体，帮助他们解决生活中的困难，被誉为“好大姐”“贴心人”‌。\n谈国琴在工作中始终坚持以人为本，记录并解决居民的每一个需求和问题，她的“民情日记”记录了社区居民的点点滴滴‌。她曾帮助解决社区空巢老人李老伯的中风前兆问题，及时送医治疗，赢得了居民的广泛赞誉‌。\n谈国琴多次获得荣誉，包括2008年浙江省优秀共产党员、湖州市“十佳”杰出女性、浙江省劳动模范、全国劳动模范、全国妇女创先争优先进个人、全国三八红旗手等‌。",
