        "name": "13十三、浙江省金华市婺城区苏孟乡和悦社区党委书记、居委会主任－汪燕飞－全国优秀城乡社区工作者",
        "summary": "汪燕飞，女，1967年8月生，中共党员，大专学历，心理咨询师，现任金华市婺城区苏孟乡和悦社区党委书记、居委会主任，1996年6月参加社区工作，历任多社区书记、主任，2018年7月任现职。曾获浙江省劳动模范、全国抗疫优秀城乡社区工作者等荣誉，当选浙江省第十四届党代表、金华市第七届人大代表，带领社区获“全国示范性老年友好型社区”“省级民主法治社区”等称号。​\n她是百姓“贴心人”：扎根基层26年，创“3153”社区工作法，用15年将老旧南苑社区建成和美社区，获40余项荣誉，打造“黄丝带”助老、“爱心冰箱”等品牌，被称“邻家大姐”。​\n她是百姓“服务人”：2018年到和悦社区（12村拆迁安置社区）后，复制成熟品牌，还引进安防体验馆、建设省级示范居家养老服务中心等10多个项目；组建“草鞋”劝导队等队伍及29家社会组织，创新500人“红领巾”楼道长队伍，以“小手拉大手”带动居民参与治理。​\n她是百姓“暖心人”：借“数字+网格”搭建410个四级微网格，实现信息传递、民访代办等线上解决，提升居民幸福感，始终以群众满意为目标，带领团队推进社区发展。​",
