        "name": "15十五、浙江省宁波市北仑区红领之家社会服务中心党支部书记、主任－陈军浩－全国优秀党务工作者",
        "summary": "陈军浩，1969年10月生于宁波北仑，宁波工程学院企业管理专业校友，现任北仑区红领之家社会服务中心党支部书记、主任，宁波市志愿者联合会副会长、市劳模工匠协会副会长，获全国岗位学雷锋标兵、全国最美志愿者、中国好人等荣誉。​\n他深耕公益多年：2001年在民政与街道支持下，创办宁波市首家民办非企业性质的牡丹社区服务站，服务老弱残等特殊群体；2008年底承接81890北仑分中心管理，半年内求助热线超1.3万个，办结率100%，回访满意率98.6%。\n2012年，他牵头成立“红领之家”，设计了敬老、导医等十大服务项目，打造“红领民生集市”15分钟便民圈与“红领反诈”项目；2014年起带领团队承接社区矫正，以“去标签化”模式助特殊人群以志愿者身份参与公益、融入社会。其事迹获广泛认可，还受邀参加国际社区矫正研讨会，展示中国相关创新实践。​",
