        "name": "19十九、浙江省绍兴市柯桥区柯桥街道立新社区党委书记、居委会主任－莫慧英－全国优秀城乡社区工作者",
        "summary": "莫慧英‌，女，1978年7月出生，中共党员，现任绍兴市柯桥区柯桥街道立新社区党委书记、居委会主任。她扎根基层18年，始终以“为民服务的情怀、俯首躬耕的姿态”作为工作的追求与准绳‌。\n莫慧英在慈善服务上担当作为，抢抓“乐善码头”省级社会治理和服务创新实验区项目创建契机，建立社区分码头。截至目前，立新社区慈善工作站已收到捐款超40万元，累计开展遭遇家庭突变应急等救助500余人次‌。她在为老服务上彰显温度，打造“幸福享老立新更好”特色品牌，成立全市首个“伴聊银龄”陪聊团，开展陪聊活动60余场，惠及老人500余人，带领社区成功创建“全国示范性老年友好型社区”‌。\n面对老旧小区既有住宅加装电梯“推进难”问题，莫慧英创新居民协商“六步工作法”，成功建成并投运柯桥区首台既有住宅加装电梯‌。此外，她在数字治理上勇挑重担，完成全市首批“智慧云”社区建设，率先推行社区智能化管理，为绍兴市社区管理数字化改革提供可借鉴、可复制的经验样板‌。\n作为浙江省第十四届人大代表，莫慧英立足基层工作，积极履职建言献策，提出关于推进公共服务“七优享”、建立多元化社区养老服务体系、强化业委会规范化建设等多条建议，为推进基层治理贡献力量‌。",
