        "summary": "原永辉，男，汉族，1973年7月生，山东荣成人，高中学历，中共党员，浙江省曹操出行网约车司机车队长，从业近8年，曾获浙江省劳动模范、“五一劳动奖章”等荣誉，带领车队参与金砖国家峰会、杭州亚运会等保障工作。\n他是“移动的安全堡垒”，独创“三查三检”工作法（出车前排查、运行中监测、收车后复盘），安全行驶50万公里，连续8年零事故零违章。​\n他是“城市摆渡人”，总结“五心服务法”，为外地乘客手绘路线图、帮语言障碍者设计交流法，备便民物品，保持标准驾驶，58个月平台服务评分99.9分。​\n他是行业引领者，参与编写《网约车安全服务标准化手册》（12个模块），创新“场景化教学法”培训司机1000余人，学员服务评分平均提升15%。​\n他还是“公益先锋”，带队开展高考免费接送、寒冬送姜茶、疫情转运物资等公益活动，在亚运会期间带领2000人团队完成乘用车保障，以行动诠释劳动者精神。",
