        "summary": "施仁利，浙江省台州市天台县中部和合调解团团长，台州市地方立法市民库成员，获“全国模范人民调解员”称号。1988年扎根基层治理，秉持“情理法相融”理念，累计化解纠纷1300余件（含非正常死亡案50余起、跨乡镇重大案40余起、群体性矛盾20余起），涉案金额超千万元，创办的“老施调解工作室”获评“省级金牌人民调解工作室”。\n他创新机制，总结“三早”调解机制、“三免”原则，独创“面对面”“背靠背”“心贴心”调解法，常驻社区夜校授课，被群众誉为“公正老娘舅”“矛盾灭火器”。​",
