        "summary": "郭文标，浙江温岭人，第十四届全国人大代表，温岭市石塘海上平安民间救助站创始人，获国际“海上特别勇敢奖”、全国道德模范、全国劳动模范等荣誉，海上救援人数打破吉尼斯世界纪录。15岁起投身海上义务搜救，四十余年初心不改。​\n他坚守救援使命，以“有呼必出，有危必救”为信条，电话号码成“海上110”。截至2025年，带领团队救援500余次，救助船舶570余艘，挽救1800余条生命，接190余名逝者归乡，曾在台风“麦莎”中救下4名渔民，在凶险航道救回17名船员。​\n他组建专业团队，2008年成立全国首家海上民间救助站，贷款造救助船，建立“20分钟应急响应”机制，现拥有10余艘船、40余名救援人员，救助范围北至济州岛、南达台湾海峡，还推动两岸首份民间救助合作协议签订。​\n他勇担代表职责，在渔船设“基层单元海上联络点”，扫码听民意，围绕渔区发展提多项建议。同时牵头海洋保护，以“小蓝之家”回收海洋垃圾，参与的“蓝色循环”项目获联合国“地球卫士奖”，用行动守护渔民与海洋。",
