        "name": "23二十三、浙江省台州市仙居县留守儿童之家“东篱之家”负责人－王雪娟－全国三八红旗手",
        "summary": "王雪娟，浙江省台州市仙居县“东篱之家”负责人，获全国“十大爱心杰出人物”、浙江省三八红旗手、2024年度全国三八红旗手等荣誉，2016年家庭获评“全国文明家庭”并受习近平总书记接见。2004年起投身留守儿童关爱事业，坚守二十年初心不改。​\n她实现从“爱心妈妈”到“公益带头人”的蜕变。返乡创办仙居首个民间儿童关爱机构“东篱之家”，创业初期克服经费短缺、人手不足等难题，白天教书、晚上手工义卖筹钱，数十次跑部门争取支持。如今“东篱之家”已扩至2000平米，累计帮扶留守儿童、困难儿童526名，辅导超1.5万人次。​\n她倾注真心，呵护儿童成长。熟知每个孩子情况，建个人档案、组织亲子视频聊天，最多时同期照料80余名留守儿童，现有30多名儿童常在此学习、5名孤儿在此生活。首批受助孩子长大成人后，还主动回“东篱之家”做志愿者。\n她以公益星火传递大爱。推动“东篱之家”在仙居20个乡镇设分部，上线德育智护平台，帮扶留守儿童2000余人次、完成“微心愿”800余个；成为省内外研学基地，2024年暑假联动7所学校开展“春泥计划”，百余名师生参与。",
