        "name": "24二十四、浙江省温州市乐清市仁和社会工作师事务所理事长，乐清市社会工作者协会副会长－黄首东－全国专业社会工作领军人才",
        "summary": "黄首东，男，1980年生，中共党员，大学本科，国家社会工作师、二级心理咨询师，乐清市仁和社会工作师事务所理事长，乐清市社会工作者协会副会长，首批温州市“瓯江红”社工CEO，浙江省社会工作师协会常务理事，获“全国专业社会工作领军人才”“浙江省最美禁毒人”等荣誉，为浙江省（温州市）高层次C类人才，擅长专业社会工作服务与研究。​\n他扎根基层，2013年创办浙江省首家民办禁毒社工机构——乐清市仁和社会工作师事务所，开创民办禁毒社工机构参与基层治理先河。带领团队以“社+志”模式，实施“北回归线计划”“禁毒心灵加油站”等项目，创新“五大工作法”与“六位一体”结合的“仁和立体帮扶模式”，服务涉毒人员及困境对象。​\n其团队开设的禁毒公益项目，整合“社工+心理咨询师+专业人士”力量，提供心理辅导、防复吸训练等服务，获政府与居民肯定。截至目前，累计为800多名药物滥用者提供心理服务，动员160名阿片类成瘾者参与美沙酮治疗；通过“六帮一”措施，联合社区民警、医生等开展帮教，将关怀送抵涉毒人员，为基层社会治理创新贡献专业力量。",
