        "name": "25二十五、浙江省温州市鹿城区松台街道桂柑社区原党委书记、居委会主任－柯建华－全国人大代表、全国三八红旗手",
        "summary": "柯建华，女，1967年11月生，中共党员，温州市鹿城区松台街道桂柑社区原党委书记兼主任，2002年起从事社区工作22年，获“全国三八红旗手”“浙江省优秀共产党员”等十几项荣誉，当选第十三届全国人大代表、浙江省第十四次党代会代表等。​\n她是社区“带头人”。2004年任桂柑社区“当家人”，牢记习近平同志调研嘱托，带领社区从“老旧小区”蜕变为“幸福宜居小区”，获全国创建文明社区示范点、全国文明单位等200多项荣誉。\n她是群众“暖心人”。成立“柯大姐工作室”，日均接待群众十几拨，解决化粪池堵塞等“关键小事”；针对1900多位老人养老需求，创办温州市首家居家养老服务照料中心，设“114”一键通服务；连续10年办“桂柑慈孝日”集体生日会。​\n她是老人“贴心人”。腾出700平方米建社区养老服务中心并升级为邻里食堂，推助餐上门服务；开办社区老年大学，设13个班、300余名学员；在小区划“亲情车位”，供子女看望老人免费停2小时。​\n她是安定“守护人”。破解老旧小区无物业收支难题，争取创建项目；组建12支社区义工队，带头巡逻，义工从10人扩至63人，社区连续十年获市级平安社区。",
