        "summary": "周雪飞，女，1975年12月生，中共党员，大学本科，国家中级社会工作师，现任鹿城区松台街道郭公山社区党委书记兼居委会主任。2004年3月参加社区工作，2012年1月任现职，曾获温州市二等治安荣誉奖章、浙江省第六次全国人口普查先进个人、浙江省优秀教育工作者等荣誉，带领社区获得“浙江省社会组织党群服务中心示范点”“全省城乡社区治理和服务成绩突出集体”等省级称号。\n她以“让居民过幸福生活”为目标，遵循“一核多元、育人为本、善治善能”理念，构建“郭公善治”模式，形成“共建共治共享”格局。扎根社区十余年，创新打造“社区社会组织党建基地”，引入第三方慈善组织，以“郭公爱吧”为品牌构建“五社联动”下的“1+1+5”模式，孵化1家社工机构、组建31支志愿服务队。​\n她活用“人大代表联系点”收集民需，推动各小区成立“红色管家”队伍、建联席会议制度，联动多方破解治理难题，环境、交通、邻里关系显著改善，居民幸福感满意度大幅提升。​",
