        "summary": "李群微，女，1977年8月生，中共党员，大专学历，现任瑞安市安阳街道育才社区党总支书记、居委会主任。2004年12月参加社区工作，2010年9月任现职，曾获“浙江省担当作为好支书”“浙江省兴村治社名师”“温州市抗击新冠疫情先进个人”等荣誉，战“疫”事迹登“学习强国”，被誉为“社区热心人、居民贴心人”。​\n她深耕社区12年，办好民生小事。2019年深夜发烧时，2小时化解居民武力冲突纠纷；率全市先开办“四点半学校”，组织干部、志愿者义务看管学生，解上班族后顾之忧；推动建成温州首个社区“生态科普馆”，解决群众学习需求。​\n她创新治理模式，提出“党建・家”系统模式，建“红色服务综合体”，创“和韵”家园品牌；推区域化党建“六同工作法”，以“错时共享停车”解停车难与校园周边拥堵；引公益创投资金，建瑞安首家社区室内公益影吧。​\n她发挥示范作用，育才社区累计接待省内外参观4万余人次，在“红色管家”等党建试点成绩突出；做好“传帮带”带动兄弟社区发展；在疫情期间交出社区“零感染”答卷，以实际行动彰显党员担当，成为居民心中“最美社区书记”。​",
