        "name": "28二十八、浙江省舟山市定海区干览镇党委委员、新建社区（村）党支部书记－余金红－全国优秀党务工作者、全国三八红旗手",
        "summary": "余金红，女，1966年2月出生，大专学历，2000年12月入党，现任舟山市定海区干览镇党委委员、新建社区（村）党支部书记。曾获全国三八红旗手标兵、全国优秀党务工作者、浙江省劳动模范、浙江省“十大强基先锋”等荣誉，2023年9月任杭州第19届亚运会火炬传递舟山站火炬手。​\n自任村支书以来，她始终以群众利益为先，带领村民致富、推动社区发展。坚持党建统领，立足本地打造以全国艺术院校大学生实习采风基地、创意壁画村、艺术培训创作基地为特色的“南洞艺谷”，有力带动社区旅游经济发展；筹资完善社区基础设施，推进美丽乡村建设，优化群众生活环境，繁荣基层文艺事业。​\n此外，她依托“网格化管理、组团式服务”平台，成立“阿红书记工作室”，累计帮助群众解决实际问题180余件，以实干赢得百姓充分认可。",
