        "name": "3浙江省杭州市拱墅区天水街道灯芯巷社区原党委书记－朱雅仙－全国优秀党务工作者、全国三八红旗手",
        "summary": "朱雅仙，女，1960年出生，浙江杭州人，1997年加入中国共产党。2001年，朱雅仙因企业破产下岗后，成为杭州市下城区（现拱墅区）天水街道灯芯巷社区的一名普通社工。凭借对社区工作的满腔热忱和真诚服务，她逐渐成长为社区党委书记、居委会主任，并成为杭州第一位由居民“海选”出来的居委会主任。她以“运动员的体魄，科学家的思维，宰相的肚量，相声演员的口才，为民服务的诚心”作为工作要求，带领社区获得诸多荣誉，成为社区居民心目中的“不二人选”。\n朱雅仙获得全国三八红旗手、全国优秀党务工作者、全国小巷总理之星、浙江省优秀共产党员、浙江省三八红旗手、杭州市优秀共产党员、“‘十五’期间杭州市优秀社区工作者”、杭州市“双十佳”创业新星等荣誉。",
