        "summary": "曹琛，女，现任浙江省杭州市上城区小营街道小营巷社区党委书记，是第十四届全国人大代表，并曾担任第十四届全国人民代表大会第一次、第二次、第三次会议主席团成员。曹琛自2016年起担任上城区人大代表，2018年4月上任小营巷社区党委书记‌。\n曹琛在社区工作中有着丰富的经验和显著的成就。她关注社区治理创新和服务升级，特别是在老龄化社区管理中，提出了多项创新措施。例如，她推动了“小雨共享厨房”项目，为独居老人提供一个安全温馨的做饭和用餐环境‌。此外，她还发起了“小雨伴我”项目，包括“小雨送餐”“小雨馒头”“小雨农场”“小雨改造”等多个服务项目，编织起基层治理的全周期服务‌。\n曹琛的工作得到了广泛的认可。她在2020年被全国妇联宣传部、民政部基层政权建设和社区治理司授予“致敬了不起的她·城乡社区抗疫巾帼先锋”称号‌。她的工作不仅改善了社区居民的生活质量，还推动了基层社区治理的创新和发展。",
