        "summary": "张爱民‌，1965年生，原杭州市西湖区翠苑街道翠苑一区社区党委书记。他凭借对社区工作的热爱和一名共产党员的热情，于2004年走上了社区书记的工作岗位。张爱民始终坚持以基层党建为抓手，以居民需求为导向，以社区治理创新为动力，努力践行“民呼我应、民求我为”的工作宗旨‌。\n张爱民在工作中注重深入群众，了解居民的实际需求。他每天在社区里多走走、多问问，用脚步丈量民情，了解居民的需求和困难。无论刮风下雨，他都会在七点半之前上班，与居民们打招呼、聊家常，逐渐赢得了居民的信任和支持‌。\n张爱民在社区工作中取得了显著的成绩，推动了多项民生事业的改善。他推动了老年食堂的建设和升级，解决了老年人的就餐问题。2003年，在时任浙江省委书记习近平同志的指导下，翠苑一区建成了杭州市首家社区老年食堂，随后经过多次升级，现在的老年食堂面积已扩展到近300平方米，并提供健康指导服务‌。\n党建工作好不好，不看墙上，而看群众的脸上。2017年10月张爱民作为党的十九大代表，将印满翠苑一区居民幸福笑脸的画册带到了北京。",
