        "summary": "章忠萍，男，1971年12月出生，现任杭州市西湖区文新街道骆家庄社区党委书记、居委会主任，骆家庄股份经济合作社董事长。他自2005年5月起担任骆家庄股份经济合作社董事长，2013年4月起担任骆家庄股份经济合作社党委书记，2018年12月起担任骆家庄社区党委书记。作为土生土长的骆家庄人，章忠萍经历了骆家庄土地承包、村办企业、征地拆迁、家园重建等重要发展阶段，参与了股份合作制改革、集体经济转型升级等工作，见证了骆家庄从一个以农耕为主的江南村落蝶变为城区黄金板块的“明星村”。",
