        "name": "7浙江省杭州市志愿者协会综合队九分队队长－顾雅娟－全国优秀志愿者",
        "summary": "顾雅娟，女，55岁，杭州市志愿者协会综合队九分队队长，从事志愿服务7年，2006年4月参与第一届休博会志愿服务后，加入志愿者协会综合队并任九分队队长，秉持“我志愿，我快乐！”的信念深耕志愿领域。​\n她多次参与重大事件服务：2007年抗台风“罗莎”；2008年抗击冰冻雨雪灾害，在杭州城站火车站服务八天八夜，为返乡农民工提供咨询、帮提行李等服务，还送免费姜茶，获浙江省政府“抗击雨雪冰冻先进个人”；历届“西博会”均参与服务，2007年、2009年获市政府“西博会”十佳志愿者。​\n2008年起她任志愿者学院讲师，三年多在社区、院校宣讲志愿者理念数十次，两次获“优秀志愿者讲师”；2009年参与“微笑亭”、文明劝导活动的组织服务；2010年作为领队服务“上海世博会宜居城市高峰论坛”；2011年服务全国第八届残运会，参与火炬接力、赛事保障，帮助残疾人运动员彩排、接送及引导观众，入选杰出志愿者候选名单。此外，她还用相机记录、在论坛展示志愿者风采。",
