        "summary": "王正平‌，男，1956年出生，现任安吉县人民调解委员会主任，省一级人民调解员。自1989年起，王正平在安吉基层司法所担任人民调解员，累计化解矛盾纠纷3000多件，被誉为老百姓心中的“老娘舅”‌。\n王正平的工作经历丰富，他不仅在调解工作中表现出色，还积极参与基层社会治理。他所在的正平工作室被评为省级金牌调解工作室，其带领的调解团队在安吉县社会矛盾纠纷调处化解中心发挥了重要作用，成功化解了中心95%以上的矛盾纠纷‌。\n王正平的工作理念是“慢慢来，只要功夫深，铁棒磨成针”。他强调调解需要耐心和细心，通过融合法律、道理和情感来化解矛盾，确保老百姓的心结得以解开。他的工作不仅限于调解，还积极参与信访工作，帮助老百姓解决实际问题，赢得了广泛的赞誉‌。",
