        "name": "9浙江省湖州市德清县人民调解委员会“德清嫂”调解品牌工作室调解员－姚惠文－全国三八红旗手、全国模范人民调解员",
        "summary": "姚惠文，浙江省湖州市德清县人民调解委员会“德清嫂”调解品牌工作室负责人。2020年从社区退休后，带领3名调解员组建工作室进驻县社会治理中心，四年来处置邻里、劳资、合同等各类纠纷，为群众纾困解难，团队探索的“四步四诊”工作法入选浙江省新时代“枫桥经验”标志性成果，入驻相关陈列馆。​\n她坚守“德文化”引领，汇聚团队向心力：联动开展“基层行”“固定解纷日”等活动，通过摸底、宣教、疏导等措施，打通多元解纷“最后一公里”。​\n她聚焦精准服务，激活内生力：以“老中医”思维研制“药方”，用“望诊于形、闻诊于情、问诊于源、切诊于症”的“四步四诊”工作法高效解纷，如成功调解三姐妹赡养父母纠纷、化解结婚28年夫妻离婚矛盾，助家庭重归和睦。\n她注重提升培育，扩大影响力：打造专属LOGO、统一标识服装，塑造江南特色形象；团队事迹获《法治日报》等媒体报道200余篇。她秉持“以心换心”，按纠纷类型灵活处置，在法度中传递服务温度，以群众满意笑容为价值追求。​",
