        "name": "1安徽省阜阳市颍州区西湖镇党委副书记兼白行社区党委书记－闫永志－全国优秀党务工作者、全国人大代表",
        "summary": "闫永志，男，汉族，1958年6月出生，中共党员，现任阜阳市颍州区西湖镇党委副书记兼白行社区党委书记，十四届全国人大代表。\n2006年至2010年，闫永志任白行村党总支书记期间，针对村民纠纷多、上访多等问题，积极探索出“四事工作法”。由村民组长、村“两委”成员等组成代表逐户排查化解问题，形成“代表理事”工作法；代表理事不能解决的问题，由闫永志当面与群众沟通交流，形成“老闫说事”工作法；遇到“老闫说事”解决不了的问题，组织老党员、老干部等“五老”人员化解，形成“五老调事”工作法；经过“五老调事”仍无法解决的问题，借鉴“四议两公开”做法，提出“群众议事”工作法，让身边人评身边事，确保矛盾纠纷不出村。\n2011年4月8日，习近平同志视察白行村，对闫永志首创的“四事工作法”给予充分肯定。闫永志牢记嘱托，不断完善该工作法。到2017年，社区矛盾纠纷化解率达100%，实现“零上访村”目标。2018年全省信访工作现场会在白行社区召开，“四事”工作法基本形成。\n闫永志首创的“四事四权”工作法，是自治、法治、德治融合的基层民主实践，是学习贯彻习近平新时代中国特色社会主义思想法治思想的生动体现。",
