        "summary": "邢春桂，女，中共党员，1965年2月出生，大专学历，初级社会工作师。1985年9月参加工作，先后担任当涂县湖阳镇大邢小学民办教师、花山区健康幼稚园幼师、新风一村居委会副主任、新风社区居委会副主任、主任、党委书记职务，现任金家庄街道新风社区党委第一书记。\n她深耕社区26载，全心全意扎根基层，牵头打造了“五治党建”“一树四助”“民情360”等社区治理工作法，创新培育了“初心园”“幸福路上红木屋”“家教有约”“风警巷”“风中的家”“花家常·网格楼事会”等项目品牌。她运用“三用群众法”，发动居民人人参与社区治理，共建美好家园，把一个老旧社区建设成了“全国文明单位”“全国和谐社区建设示范社区”“全国最美志愿服务社区”。在社区工作期间，邢春桂荣获了“全国优秀党务工作者”“中国好人”“安徽省优秀共产党员”“首届‘江淮优秀社工’”等各级荣誉50多项，2012年7月当选为党的十八大代表。",
