        "summary": "张仕仪，女，1961年2月生，安徽枞阳人，中共党员。自1980年起扎根枞阳县枞阳镇新华社区工作，1995年担任社区党组织书记，2012年兼任居委会主任，深耕基层40余年，将老旧社区治理成为全国示范标杆。\n她创新推行“三网合一”网格化治理模式，以300户为单元划分大网格、60户为小网格，精准对接居民需求，年均联动共建单位解决电路检修、危墙修缮等民生问题近百件。为解决空巢老人“吃饭难”，她于2019年推动建成全县首个社区老年食堂，并为行动不便者提供送餐服务，累计服务超3万人次。她还发放5000张“为民服务卡”，24小时接听居民诉求。\n2020年疫情与汛情叠加期间，她冲锋在前，带领团队仅用5小时转移1384名群众，带伤坚守防汛一线；同步助力企业1天内复工复产，为217名务工人员办理健康证明。\n因贡献突出，张仕仪2021年被中共中央授予“全国优秀党务工作者”称号，2020年获评安徽省敬老爱老助老模范人物，2021年获评“安徽好人”，2023年获评安徽省“最美婆婆”。",
