      //   "summary": "黄晔，福建省松溪县松源街道东门村人，1981年8月出生，中共党员，在社区工作领域贡献卓越。\n2018年3月，加入松源街道南门社区工作者队伍中，自此深耕社区领域。2020年12月任松源街道茶香社区负责人、支部副书记，2024年5月起担任西门社区党总支书记、居委会主任，始终以热忱与担当推动社区发展。\n2020年疫情防控期间，黄晔展现非凡担当。作为排查工作组成员，疫情一级响应启动后，他即刻返岗，每日处理大量电话、公文，细致摸排返乡人员信息，是尽责的“排查员”。同时，他为居家人员保障生活、增强抗疫信心，积极宣传防疫知识，化身无畏“逆行者”。工作中，他加班加点，身体抱恙仍坚守，舍小家为大家，不折不扣落实部署，以“实干家”“老黄牛”的姿态，用行动诠释初心使命，彰显责任担当。\n凭借在抗疫中的突出贡献，2020年12月，黄晔荣获全国抗击新冠肺炎疫情优秀城乡社区工作者称号，这份荣誉既是对他过往付出的肯定，也激励着他在社区工作中继续发光发热。",
