        "summary": "朱林，女，江西省宜春市樟树市福城街道福城社区党支部书记、居委会主任。2002年扎根社区，23年践行“上为政府分忧，下为百姓解难”初心。面对辖区1342户5000余人的复杂社情，率5名社区干部以“零距离服务”创新治理，获“小巷总理”“活档案”称号，2022年获评“全国优秀城乡社区工作者”，“三认四提四知”网格工作法成宜春基层治理标杆。​\n她是社区治理“破题先锋”，2014年负责3个无物业小区改造，数百次上门化解居民抵触，清除违建1526处，解决水管破损等顽疾；推动鑫隆锦绣城设“居民议事会”，引导居民自筹资金装36个摄像头，每月例会商民生，形成自治格局。​\n她是矛盾化解“金牌调解员”。设“林姐调解室”，年均调处纠纷超千件，2024年化解矛盾1321件，化解率99.5%（如调解商铺水管损坏索赔纠纷）；随身携带12本民情日记，11年调解近千起纠纷，实现服务“零投诉”。\n她是民生服务“温情守护者”。首创“三认四提四知”工作法，网格员“认路认房认人”，“提房知人、提人知事”，日均步行2万步，为独居老人送药、帮残疾人协调上门核酸；组织“邻里节”“重阳宴”，举办文艺晚会表彰“身边好人”，以节目凝聚社区认同。",
