        "summary": "吴乐怡，江西抚州临川人，中共党员，2005年投身社区工作，深耕近20年。2018年任西大街社区党委书记、居委会主任，2021年当选抚州市、临川区两级人大代表。​\n她以“党建+多元服务”为核心，打造“党建+时光益站”“党建+新就业群体服务站”，将社区建成全国示范性老年友好型社区，获“将社区变成家”赞誉。​\n她构建“一老一小一新”服务体系：组织12支“敲门行动”分队，走访独居老人600余人次，帮办339件事，推动“社区综合养老”，帮助19位老人入住养老中心；创“童伴妈妈”机制，26名党员帮扶34名留守儿童，解决530余个难题；建新就业群体服务站，开展42次活动，惠及1800余人次。还推动高龄津贴等“三审合一”，2024年惠及342名老人，获央视报道。​\n作为人大代表，她借“12345人大代表民声专线”解决10余条民生问题，推动老旧小区改造；提出“无物业小区改造”建议成重点议案，争取120万元改造资金，惠及800余居民。",
