      //   "summary": "山东省济南市槐荫区中大槐树街道裕园社区党委书记刘云香扎根社区24年的历程，不仅是一部基层管理的创新探索史，也是一段社区情怀与治理相结合的协奏曲。\n在刘云香的工作字典里，创新永远是做好社区工作的重要法宝。用小微企业“托举”大幸福。“我在上下班的路上、吃饭时甚至临睡前，都在思考如何做好‘经济账’，让社区的业态‘活’起来，只有调动了民生资源和社会力量的参与，才能带来持久的受益和循环投入。”\n一直以来，刘云香首推“党建+信托制物业管理”模式，裕园社区积极探索通过打造创新品牌，建设高质量美好生活的路径，组建了38个草根组织，创办了社区“公益积分制”“云香激励金”“一元互助金”等多个互助平台；建成全省首家社区“阳光温暖超市”“爱心在线居家养老服务社”等“五位一体”服务场所；在全国率先引进智慧停车管理平台，解决了老旧小区停车难题……其中，让刘云香最引以为豪的是，裕园社区在全省范围内首推“党建+信托制物业管理”，破冰小区物业管理难题。\n“给社区一点阳光，社区就会灿烂。”刘云香表示，社区治理，其实就是一种情感治理。正是通过这种情感维系，干部、群众、志愿者队伍联结为深厚的纽带，大家以社区为家，以服务居民为荣。",
