        "name": "2山东省济南市天桥区工人新村南村街道西区社区党委书记－田象霞－全国优秀共产党员",
        "summary": "田象霞，天桥区工人新村南村西区社区党委书记。1983年5月参加工作，1994年11月入党。从事社区工作38年，她始终保持共产党员本色，把岗位当作奉献的平台，时刻心系群众、处处为民着想，让昔日基础设施差、管理难度大的老旧开放式社区，蜕变成了群众乐居乐业的全国和谐社区建设示范社区。她也从一名普通社区工作者变成家喻户晓的“全国劳动模范”，先后获评“全国百姓学习之星”、山东省“担当作为好书记”并荣记一等功、“山东省优秀党务工作者”“山东省劳动模范”“山东省三八红旗手”“山东省文化共享能手”等荣誉称号，曾担任山东省第十一次党代会代表。\n从青丝到白发，从青春到花甲，田象霞用38年的热情和辛勤努力，在最平凡的基层工作中践行了一名共产党员全心全意为人民服务的初心。",
