        "summary": "张冬香是有着30多年党龄的退休党员。近年来，她带领平均年龄63岁的老党员先后成立了冬香好妈妈工作站，组建了红色宣讲团、党员合唱团、家事调解队、巾帼银发宣传队，开展党史学习教育、文明创建等公益宣讲活动700余场；创新探索“冷却降温法”“换位思考法”“双方互夸法”等家事调解工作法，努力实现了“小事不出社区、大事不出街道”，为助力基层社会治理贡献了力量；开辟冬香好妈妈疫情心理咨询疏导热线，带领10余名志愿者公布联系方式、提供上门服务，共接受群众心理咨询900余次；带领400余名党员群众志愿者，坚守在全市100余个小区楼院的疫情防控一线，以实际行动守护人民群众生命安全和身体健康，受到了社会各界的高度称赞。\n由于工作表现突出，焦作市冬香好妈妈工作站党支部先后获得“全国先进基层党组织”“全国三八红旗集体”“全国离退休干部先进集体”等荣誉称号，张冬香也先后荣获“第二届全国文明家庭”“全国最美家庭”“河南省优秀党务工作者”“河南省巾帼建功标兵”等荣誉称号。",
