        "summary": "陶久娣，1969年12月生，汉族，中共党员，现任湖北省武汉市东湖生态旅游风景区东湖新城社区党总支书记、居委会主任。\n陶久娣曾获武汉市优秀党务工作者、武汉市创建国家卫生城市先进个人等荣誉称号。2020年9月8日，中共中央表彰她为全国优秀共产党员。2020年4月23日，陶久娣入选“城乡社区抗疫巾帼先锋”。2021年，陶久娣成为守护国家安全代表人物。",
