        "summary": "白宓，女，1971年7月出生，汉族，中共党员，助理社工师、现任东西湖区常青花园第一社区党委书记、居委会主任。武汉市十四届政协委员、东西湖区第十一届人大代表。2020年获全国抗击新冠肺炎疫情先进个人、2021年获湖北省优秀党务工作者称号。在同事眼里她是“领头雁”、主心骨，在居民心目中她是说话贴心、办事放心、工作用心，把群众放在心里的社区当家人。",
