        "summary": "孙睿华，女，汉族，1975年9月出生，现任武汉市汉阳区琴断口街七里一村社区书记主任，汉阳区人大代表，汉阳区基层治理委员会委员。\n孙睿华从事社区工作已有整整18年，工作经验丰富。在工作中她勤勤恳恳、严谨认真、勇于创新，廉洁自律，不断提升自我，超越自我，迅速成长。近年来，她在推进社区多元共治、抓好社区治理创新上成绩显著。其所在的七里一村社区率先在全区实验“五书引领整合资源”模式，推进社区的五大转型，同时采用“七色工作法”精准服务居民，社区治理焕发了新活力，个人及其所在的社区多次获得省、市、区相关部门的表彰及肯定。同时，2018年10月民政部基政司司长陈越良到七里一村社区调研社区治理工作。2020年4月，武汉市人大常委会副主任到社区调研疫情基层治理；其个人曾先后荣获汉阳区“三八红旗手”、区优秀共产党员、区优秀妇女工作者、汉阳地区“十佳青年”、汉阳区知音英才等荣誉称号。",
