        "summary": "王波，女，汉族，1963年3月出生，中共党员，大学本科学历，武汉市江岸区百步亭社区党委副书记、管委会主任，百步亭集团总裁。中共十七大、十八大、十九大党代表，荣获全国优秀党务工作者、最美城乡社区工作者、全国优秀志愿者等称号。\n王波原是大学教师，怀着知识分子到基层去为老百姓服务的初心，1995年来到百步亭，扎根社区基层一干就是24年。她一肩挑起社区“建设、管理、服务”三副重担，带领百步亭社区18万居民和4万多志愿者，创建了一个全国文明社区、全国先进基层党组织、首届中国人居环境范例奖的社区。",
