        "summary": "汪明菊是宣恩县珠山镇上湖塘社区党总支书记、主任，从事基层工作20余年，她是群众心里的“知心人”，是社区运转的“万金油”。她在社区管理中提出“一声问候、一杯热茶”的服务理念，坚持“能办的事情一定要办好，不能办的事情也要为群众指好可以办好的单位和方法”的工作原则，高举民族团结旗帜，积极致力于民族团结工作，曾被评为“恩施州民族团结先进个人称号”，2019年9月，又被评为“全国民族团结进步模范个人”。\n汪明菊，她是一名很普通的乡镇基层干部，工作23年来虽然没有做出惊天动地的业绩，但她在平凡的工作岗位上兢兢业业，任劳任怨，不忘初心、用她的实际行动来践行共产党员的高尚品质和各民族“共同团结奋斗、共同繁荣发展”美好愿景。",
