        "name": "4湖南省邵阳市北塔区状元洲街道柘木社区党总支书记、居委会主任－李躲胜－全国优秀城乡社区工作者",
        "summary": "李躲胜，男，汉族，1985年11月生，湖南邵阳人，党员，大专学历，2017年1月参加工作，2018年7月加入中国共产党。现任邵阳市北塔区柘木党总支书记、居委会主任，2017年1月当选柘木社区居委会主任，2021年1月当选柘木社区党总支书记、居委会主任。曾于2021年6月获邵阳市“优秀党务工作者”。在职期间社区先后获评全国民主法治示范社区、全国未成年思想道德建设先进单位、湖南省第二批优秀村规民约、全市社会主义核心价值观建设示范点等荣誉、省级“扫黄打非”示范点。",
