        "summary": "关绮文，现任中山市石岐街道桂园社区党委书记、居委会主任。曾连续多年获评中山市优秀共产党员、2021年获评“中山最美妇联执委”、中山市百名基层党组织书记微党课大赛“最佳口才奖”。\n2006年从事社区工作以来，关绮文始终坚守为人民服务的初心，以群众满意为最高标准，扎根基层、拼搏奉献，以扎实的工作作风赢得了组织和群众的认可。自任桂园社区党委书记以来，她坚持以党建为引领，一手抓治理，一手抓服务，不断创新党建工作方法，探索创建“建强战斗堡垒，铺开社区一片红；引领党群齐治理，下活社区一盘棋；创建服务品牌，党群一家亲”的“三个一”工作模式，推动社区各项工作高质量发展。",
