        "summary": "王燕飞，现任广东省韶关南雄市雄州街道民主社区党委书记、居委会主任。作为南雄市第一位异地选派的女支书，辖区的每一栋楼、每一条街，王燕飞都如数家珍。自2011年3月进入社区工作以来，11年间她扎扎实实学业务，一步一户访群众，一心一意谋发展，用自己的实际行动践行着共产党员“全心全意为人民服务”的铮铮誓言。近五年来，民主社区党委获韶关市级以上表彰3项，其中，2022年5月，民主社区荣获全国五四红旗团支部、党委书记王燕飞获得韶关市级以上表彰2项，其中2022年11月，荣获全国优秀城乡社区工作者、2024年7月，荣获韶关市优秀党务工作者。",
