        "summary": "全国人大代表区燕明扎根基层26年，她积极践行党的二十大、党的二十届二中、三中全会精神，始终全心全意为社区居民解决一件件烦心事揪心事。任职社区党委书记以来，她带领社区党委聚焦民生实事，先后推动辖内老旧小区加装电梯、旧楼加装扶手、社会治理、适老化改造等工作。2010年，在陈家祠裕轻苑物业公司突然“跑路”的情况下，她带领小区居民率先成立业主委员会，开创居民自治的先河，陈家祠社区荣获全国综合减灾示范社区；2023年，她带领的蟠虬社区入选中组部先进社区案例；2025年，依托社区“民生微实事”项目，为社区总共加装了长1.1公里的爱心扶手，连起了居民回家的安心路……她带领社区做的一桩桩一件件暖心事，成为基层治理模式的“金花样板”。",
