        "summary": "李森，男，汉族，1976年6月出生，2003年8月加入共产党，现任广东省广州市天河区启智社会工作服务中心党支部书记、总干事、广州青年志愿服务启智队总队长。2016年增补为共青团中央常委。该同志注册成立了天河区启智社会工作服务中心，第一时间成立党支部，并担任党支部书记，影响和带动其他社会组织建立党组织，团结带领20多万党员、青年参与到志愿服务活动中。他所带领的团队被中央宣传部、中央组织部、中央文明办授予“全国最佳志愿服务组织”称号，其本人先后获得“中国青年五四奖章”“全国优秀党务工作者”等荣誉称号。",
