      //   "summary": "杜世雄，现任北京市昌平区霍营街道华龙苑北里社区专职工作人员，因在基层治理与民生服务中的突出表现，于2020年12月被授予“全国抗击新冠肺炎疫情优秀城乡社区工作者”称号，是居民心中扎根一线、务实担当的“贴心人”。\n他始终以“社区事无小事，群众盼即工作向”为准则，深度参与社区核心治理实践。在社区推行的“五方共建”模式中，他积极联动居委会、业委会、物业公司及社会组织，参与搭建共商共治平台，助力破解一系列民生“硬骨头”——从推动19部老旧电梯更新（争取超长期国债支持并协调旧电梯回收补充资金缺口），到落实市政水置换、路灯升级、自行车棚装充电桩等民生项目，再到牵头解决排污井扩容、休闲场地打造等居民急难愁盼，每一项进展都凝聚着他的奔                                                              走与付出。\n在日常服务中，他既是“霍营管家”队伍的重要一员，参与日常巡查、邻里纠纷调解与政策入户宣传，又深度投身垃圾分类等重点工作：协助建立楼门沟通群与“点单－派单－接单”快速响应机制，动员志愿者开展桶站值守与分类培训，针对老人楼道堆物问题推动建立暂存点与清运制度，以“小切口”做实基层“大治理”。疫情期间，他更是冲锋在前，以细致的排查、值守与民生保障工作，守护着社区近3000名居民的平安，用行动诠释了基层工作者的责任与坚守。\n作为社区治理的“螺丝钉”，杜世雄始终扎根群众中间，将个人工作融入社区发展，在政策落地、矛盾化解、服务升级的每一个环节践行初心，成为社区从“脏乱差”到“洁净美”蝶变进程中不可或缺的基层力量。",
