        "summary": "伊然，女，蒙古族，1967年12月生，现任北京市昌平区龙泽园街道龙泽苑社区党委书记、居委会主任，北京市第十五届人大代表等职。她扎根该社区15年，社区为1998年建成的老旧小区，2005户6836人，呈“三偏四多”特点，90%以上居民熟知这位“守卫者”“暖心人”“大管家”。\n她秉持“党建引领、多方共建”原则和“为社区者，不慢其民”理念，创“魅力龙泽议事厅”，12345解决率和满意率100%，团队“四五六工作法”获中组部全国先进典型社区案例。\n她带“两委”践“四勤”（嘴、眼、手、脚勤）建熟人社区，守“五清”（基本情况、重点群体等清）服务群众，协调70万元公益收入翻新围栏；借“回天大脑”实现信息化管理。牵头“六联”共治平台，联动54家单位，开办老年大学设18个兴趣班，每年组织近百场文体活动，惠及万余居民。\n社区获得国务院无邪教示范社区、北京市先进党组织等多项荣誉，居民称“比110快、比120近”。她个人荣获全国妇联系统劳动模范、全国三八红旗手、北京榜样、首都道德模范等多项殊荣。",
