        "summary": "李德青，东城区交道口街道福祥社区党委书记，2018年调任后以“当家人”身份扎根社区，日均万步巡胡同，聚焦老胡同焕新与居民需求，深耕基层18年（2006年起）获居民认可。\n福祥社区毗邻南锣鼓巷，辖内雨儿胡同有700余年历史，含齐白石旧居。2018年底该胡同启动修缮，她多次深夜、周末上门沟通，历时两月说服首户居民，坚持“一院一方案、一户一设计”，半年后居民顺利回迁。\n她推动30号院（原清朝值年旗衙门杂物房）变身公共空间，落地居民提议的“槐香客厅”等五大服务功能，成为居民议事、活动的精神家园。此外，她创新“五新”党建品牌，以党建引领基层治理、多元参与、科技赋能等，激活社区活力。\n她秉持“共建共治共享”理念，用心服务居民，从初涉社区工作的“门外汉”，成长为推动老胡同居民过上新生活的“领路人”，让历史街区兼具古都风韵与宜居属性。",
