        "summary": "邵雪松，女，汉族，1977年4月出生，中共党员，本科学历，现任房山区西潞街道苏庄三里社区党委书记兼居委会主任，兼任中共北京市第十三届党代表及北京市第十六届人大代表。\n自2013年担任社区书记以来，她深入走访每户家庭，亲自处理1500余件群众诉求，成功调解近百起纠纷，并集资改善困难居民住房条件，长期救助重病患者。她率先垂范，多措并举，社区6个老旧小院全部获评北京市生活垃圾分类示范小区。\n她于2015年创新提出“育网式”精细化治理工作法，显著提升基层党组织服务效能。自2021年起，她积极推广践行西潞“好邻居”协同治理党建品牌，倡导居民群众、机关单位、企业商户在党建引领下打破界限，互做真诚相待的“好邻居”。通过实施“党建共建、资源共享、有事共商、难题共解、发展共促、文化共育、安全共抓、环境共治”八项举措，构建了共治共享的新平台，有效攻克了房产证办理、水质改善、房屋修缮、停车管理、物业服务等民生难题。在此基础上，推出“六邻”党组织工作法，成功解决辖区学校1500套课桌椅的更新等问题。",
