        "summary": "邓丽华，北京市丰台区丰台街道游泳场北路党委书记、居委会主任，社区2020年8月成立后，她以党建引领多元共治，聚焦居民需求打通民生服务“最后一公里”，2020年获评北京市“接诉即办”先进个人。\n党建引领上，她创“四心”模式建队伍，“悉心”育人才、“诚心”凝合力、“细心”调分工、“用心”造氛围；将社区划为7个网格、8个党支部，“两两组队”设专属管家；提“我是12345”理念，要求干部日沉网格3小时，把书记办公室打造成政策“传达室”、服务“连心室”、问题“解决室”。\n统筹资源中，她借共驻共建破难题，建物业管理联合会，帮部队管院落、解涉军访，协调拆违建1000余平方米，获疫苗接种与核酸检测场地；以鼠患整治为突破口，发动居民清理“弃管”小区，还执着协调解决东货场路42号院无人管理问题。\n文化育人方面，她联部队搞红歌、党史竞赛等活动传红色基因；为141个单元装党建插板、设红色宣传版画；引400余册史志书籍，挖掘书法等人才组文化队伍，推动社区治理精细化。",
