        "summary": "贾秀杰，北京市海淀区万寿路街道28号社区书记，在疫情期间以“疫情就是命令，防控就是责任”为信条，带领“两委一站”社工坚守一线，用实干彰显责任担当。\n1月23日深夜，她接到任务后即刻核查外地返京人员信息，次日成立应急小组。针对开放式小区，28日协调物业封闭3个出入口，带头与社工早7点至晚10点轮班执勤，每日三分之二时间驻社区。她添加千余名居民为微信好友，深夜仍及时回复疑问与恐慌信息，成为居民信赖的“好书记”。\n她常夜宿办公室甚至通宵，超负荷工作仍为同事订菜、督促他人休息，自己紧盯民情并坚持每日总结研判问题。2月18日发现疑似密接，她迅速疏散消毒、核实信息后上报，协调隔离并发放暖心包，处置高效有序。\n6月防控升级后，她带领团队14日通宵部署，15日完成3845人核酸检测，16日扫楼确保全员覆盖。小区封闭管控期间，推行网格化管理，马不停蹄协调解决买菜、就医、设施故障等民生难题，化解各类棘手问题。",
