        "summary": "赵丽梅，欢乐蜂场“妇”字号基地负责人，2015年从城区回到平谷爱人的家乡，创办北京野馨科技发展有限公司，以带动女性增收、做强平谷蜂产业为核心，同步探索文旅融合与青少年科普，助力乡村振兴。\n她秉持“绿色办企、科技养蜂、助农增收”宗旨，引进自流蜜生产技术，在降低蜂户劳动强度的同时提升效益5至8倍；每年培育优良种王1000余只，还采购5万余元蜂箱、蜂具免费发放。她聚焦女性力量，推动蜂户与公司合作，每年帮销蜂蜜100余吨，助蜂户增收2至3倍，还手把手教女性自媒体销售、免费分享DIY蜂产品课程。\n疫情期间，她调整模式入驻电商，把直播间设到田间地头，除蜂产品外还帮果农卖大桃、玉米等，累计销售七万余单，曝光量超百万次，减少农户损失。她还将原平谷县种蜂场改造成“欢乐蜂场”综合园区，开发蜜蜂IP绘本、舞台剧等，年接待近5000个亲子家庭，带动乡村旅游。\n此外，她组织32位全职妈妈成立科普团队，建京郊首家科普实验室，开发《探索蜜蜂王国》等课程，开展千余场科普活动，惠及八万余人次，助力“双减”政策落地。",
