        "name": "1广西壮族自治区贵港市港南区江南街道廉石社区党总支书记、居委会主任－李卓献－全国优秀城乡社区工作者",
        "summary": "李卓献是广西贵港市港南区江南街道廉石社区党委书记、居委会主任，2001年投身社区工作，至今已深耕基层22年，获评“全国优秀城乡社区工作者”，始终以“服务于民、奉献于民”为目标，践行基层工作者的初心使命。\n她聚焦党建引领基层治理，将社区党组织建设标准化、服务精细化，创新推出“邻里守望耀江南，团结互助一家亲”活动，打造积分超市、邻里守望巡逻队，开展捡烟头比赛、街长选举等系列活动；还创建“红色一家、爱心驿站”等五大社区服务品牌，推动廉石社区于2015年成为贵港市首个“信息化、可视化、智能化、网格化”四位一体现代化精品社区，累计获得十五项国家级、自治区级、市级荣誉，其党建示范点曾作为全国基层党建创新论坛参观点。\n针对社区60岁以上老人超20%的情况，她牵头设立老年人活动中心、图书阅览室，联动医疗机构开展小区义诊，并邀请义工为老人提供心理疏导；面对居民难题，她带队走访红口岭小区500余户居民，集资清理垃圾、硬化空地并增设休憩设施，还帮助重病居民叶某申请低保与大病救助，缓解其家庭困境，赢得“群众有难事，就找李书记”的居民信赖。同事评价她工作勤恳、常分担压力，她则表示将继续当好居民贴心人，把群众大小事做实做好，展现新时期社区工作者的担当风貌。",
