        "summary": "谢兰，女，53岁，汉族，中共党员，现任人和街道邢家桥社区党委书记、居委会主任。\n谢兰深耕社区治理20余年，自主探索形成“幸福一生、五心服务”“六桥同治”“三步问需五步工作法”等创新工作方法，为构建基层社会治理新格局提供“两江样本”。其中“六桥同治”成功入选全国基层思想政治工作优秀案例。探索并实施了“街道+社区+派出所+居民（单位）”的四级联动联调模式，化解居民矛盾纠纷，平均每年信访调解案件纠纷30余件。她推动依法攻坚老旧小区改造重大民生工程，重庆日报以“谢兰为什么能”为题进行系列报道。",
