        "summary": "苏琼芬，中共党员，现任盘龙区东华街道文艺路社区党委书记、居委会主任。从事社区工作37年，先后获得“全国民族团结进步模范个人”“全国巾帼建功标兵”“云南省优秀村（社区）党组织书记”“云南省百名好书记”“云南省优秀党务工作者”“云南省三八红旗手”等荣誉称号。曾作为“领头羊”带领团队把盘龙区金星社区打造为全国创建民族团结示范社区的成功典型之一。按照“融入总体、以人为本、双向服务、因地制宜”的创建原则，通过“上级指导、社区主导、社会引导”的创建方式，把民族团结进步示范社区创建工作融入社区治理责任网格，以民族工作为民服务“4578”机制为抓手，营造了平等团结、互助和谐、幸福安康、文明开放的社区氛围。",
