        "summary": "者发贵，男，彝族，1977年12月生，中共党员，初中及以下学历，云南顺丰速运有限公司收派员。全国“五一劳动奖章”获得者。中国工会第十八次全国代表大会代表。自2008年入职顺丰以来，者发贵在一线收派员岗位上坚守17年，累计服务客户上万人，收派行程超过20万公里，处理收派件60余万件，做到从业以来“零投诉”。他时刻以“提升客户体验”为核心，着力解决客户发件难题，赢得客户交口赞誉。他还悉心传授新快递员工作技巧经验，在片区培养了200多名优秀的“快递小哥”，“传帮带”成效显著。他作为云南顺丰速运有限公司工会代表，有效反映和解决员工诉求，发挥了桥梁纽带作用。",
