      // {
      //   "name": "10陕西省铜川市宜君县陕西闽发房地产开发有限公司党支部书记、总经理－唐孝标－全国道德模范",
      //   "summary": "2005年，唐孝标来到铜川市宜君县发展，作为一名商人，对于唐孝标而言最重要的就是诚信，这是一个企业的“生命”，是生存之道、立业之基，正所谓“诚信者赢天下，失信者寸步难行”。在宜君这几年的发展过程中，唐孝标也始终将企业的发展融入当地经济发展和社会效益中，用自己的努力和付出带动宜君经济发展。多年来，公司先后荣获铜川市优秀民营企业、非公企业党建示范点、精准扶贫先进单位，陕西省民营企业社会诚信单位、守合同重信用企业、爱国拥军模范单位、民营企业先进党支部，以及“国家AAA级诚信企业”等荣誉。唐孝标也先后荣获陕西省“光彩之星”“陕西省优秀民营企业家”、陕西省工商联“商会建设先进个人”“关爱员工优秀民营企业家”“第五届陕西省道德模范”等荣誉称号。2016年5月，荣登“中国好人榜”，2021年11月获第八届全国道德模范提名奖。\n一是做精耕主业的“实干者”，以卓越品质铸造信誉。党的二十大报告指出“加快实现高水平科技自立自强”“增强自主创新能力”，充分体现了以习近平同志为核心的党中央对民营企业家地位、企业家创新精神的高度重视和充分肯定，这也极大地增强了唐孝标干事创业的信心和决心。今后，唐孝标将带领着公司的一班人马，努力为企业发展打开新的广阔空间，继续以高质量标准为抓手，在宜君县建成一批批高品质的高楼大厦、现代化超市、商场以及旅游度假村，为改善当地居住环境、购物环境、投资环境提供重要支撑，始终践行“老老实实做人，结结实实盖房，到哪里投资哪里就是唐孝标的家”的职业信条，不断推动企业发展迈上新台阶。\n二是做诚信经营的“践行者”，以诚信守约保障信誉。始终遵循“质量第一、信誉至上、诚信守法、持续创新、以人为本”经营理念，时刻遵守税收一分不少交、工资一分不拖欠、社会责任应担尽担这3条“铁规”，在任何情况下坚决不拖欠员工工资，坚持检查工人工资发放情况，建立工资发放资料档案，杜绝工程单位冒领工资。同时，为一线职工办理人身意外伤害保险，帮助职工解决困难，让职工们留得安心、干得舒心，用良心做企业、以诚信赢口碑。\n三是做担当奉献的“引领者”，以热心公益拓展信誉。大力弘扬企业家精神，积极履行社会责任，既担好经济发展的责任、又担好社会进步的责任，始终秉承“乐善好施、帮扶济困”和“有钱做善事，没钱做好事”的家训家风，继续发挥唐孝标500万元公民道德基金、200万元金秋助学基金作用，尽自己最大能力去帮助更多的道德模范、贫困学生。同时，主动安置下岗职工、进城务工人员、残疾人、复退军人、待业青年等，关注困难家庭、贫困学生……用一辈子来做好事、行善举，始终无愧于中国共产党员的身份，也无愧于一个民营企业家的本心。",
