        "name": "12陕西省咸阳市秦都区渭滨街道七〇四社区党支部书记、居委会主任－赵亚莉－全国优秀城乡社区工作者",
        "summary": "赵亚莉1977年参加工作，自从事社区工作以来，她几乎走遍了704社区的每家每户。社区工作，她总是抢着去干，从不计较得失，工作起来也经常牺牲节假日休息时间。在调解工作中，赵亚莉同志始终把工作重点放在“防”字上，采取得力措施，防范到位。她克服困难，组建了咸阳市老年学校，使老年人在自己家门口就能上大学，最大限度地满足了广大老年人的精神文化生活需求，为老年人搭建了一个可学、可乐的良好平台，提供更新知识文化娱乐的场所、延年益寿的乐园。为了做好创文巩固提升工作，她在社区发起成立了志愿者服务站，围绕“居民受益、让群众满意”这个中心，大力弘扬友爱、互助、进步的志愿精神。",
