        "name": "15陕西省榆林市榆阳区新明楼街道三官会社区党支部书记－李小玲－全国优秀城乡社区工作者",
        "summary": "李小玲，现任陕西省榆林市榆阳区新明楼街道三官会社区党支部书记。她深耕基层治理多年，聚焦辖区老旧小区密集、人口结构复杂、商业集聚的治理难题，以党建为引领创新实践，牵头推出 “一核引领、二线并行、三治融合、四防并举、五色服务” 的 “12345” 工作法，构建起智慧型平安社区治理新格局。\n针对贾盘石下巷等区域长期存在的乱停乱放、交通拥堵问题，她通过多方协调推动巷道翻修治理，打通商区三条关键巷道，既化解了民生痛点，又激活了商区经济活力。在她的主导下，社区搭建 “小刘说事” 调解室、“线上解民情 + 线下惠民生” 服务平台，组建 “李姐敲门” 助老队伍等特色服务载体，通过红色党建引领、银色关爱老人等 “五色服务” 织密民生保障网。从疫情防控期间的精准管控与物资保供，到独居老人生活照料、居民矛盾就地化解，她始终以 “清单化解决群众急难愁盼” 为目标，推动居民从 “服务受益者” 转变为 “治理参与者”，助力社区荣获 “全国综合减灾示范社区” 等多项荣誉。",
