      //   "summary": "王友民，中共二十大代表，现任陕西容厦集团有限责任公司党支部书记、董事长，深耕爱国拥军事业 40 余载，被誉为 “拥军经理”。他扎根陕西省渭南市高新区，以 “国为先 家为后 民为重 己为轻” 为座右铭，将拥军情怀融入企业发展与社会担当，累计投入 4300 余万元用于拥军优属工作。\n其拥军实践兼具深度与广度：在保障民生方面，企业 80% 以上员工为退役军人或军属，累计为 360 余人提供就业岗位，为 1300 余名退役军人开展免费技能培训，助力他们实现从军营到职场的转型；在支持部队建设上，与时俱进推出经济、文化、科技等多元拥军举措 —— 从为部队修建篮球场、组建军乐队、送上文艺演出，到捐赠电脑助力科技练兵，设立 10 万元 “爱军精武奖励基金”，全方位解决官兵后顾之忧。\n他牵头打造的容厦双拥展览馆，经升级后占地 6500 平方米，通过声光电等多元形式展现军民鱼水情，年接待参观者超 2.4 万人次，成为陕西省爱国拥军教育基地及高校 “大思政课” 实践平台。作为渭南市全民国防教育宣讲团成员，他走进校园、社区开展上百场宣讲，并邀请战斗英雄讲授国防课，推动尊崇军人成为社会共识。\n凭借这份执着坚守，他先后荣获 “全国爱国拥军模范”“全国退役军人服务保障先进个人” 等称号，所领导的企业获评 “全国退役军人工作模范单位”“陕西省情系国防好企业” 等殊荣，其事迹被陕西省委、渭南市委列为学习典范。",
