        "name": "17陕西省西安市灞桥区洪庆街道庆华社区党支部书记、居委会主任－党芳玲－全国模范人民调解员",
        "summary": "党芳玲是陕西省西安市灞桥区洪庆街道庆华社区党支部书记、居委会主任，2020 年 12 月被授予 “全国模范人民调解员” 称号，作为深耕基层的老党员，她以 “法理相融、情理相通” 的调解艺术，为单位型社区治理注入温暖力量。\n针对庆华社区 5600 余户居民以企业职工及家属为主、矛盾多涉及邻里相处与物业服务的特点，她牵头成立 “党芳玲调解工作室” 及 7 个调委会，构建 “一带多、聚合力” 的调解网络，通过每年评选优秀案例、推广调解经验，激活基层治理内生动力。在 “党建引领、多元共治” 框架下，她整合社区 1857 名党员、117 名楼栋长及民警、网格员等力量，将调解工作嵌入 “基础网格 — 微网格” 治理体系，实现矛盾线索早排查、早介入。\n她擅长用 “背靠背疏导 + 面对面和解” 的方式化解纠纷，既以法律条文明晰权责，又以邻里情谊拉近距离。面对居民因肢体摩擦封堵楼道、物业与业主因收费及服务起争执等问题，她联合洪庆派出所 “暖心警务会客厅” 开展联动调解，通过释法明理、协商方案，推动多起棘手矛盾平稳化解，避免事态升级。在她的带动下，社区调解与民生改善形成良性互动，累计推动安装电梯 34 部、建成电动自行车充电桩 148 处，用矛盾化解的 “小平安” 筑牢社区治理的 “大根基”。\n如今，她的调解工作室已成为 “警社共治” 的重要枢纽，通过 “法理说透、情理说通” 的坚持，让 “有事找党姐” 成为居民共识，更以 “一带多” 的传帮带模式，为社区培育出一支扎根网格的调解队伍，用实际行动践行 “枫桥经验” 的基层实践。",
