        "summary": "姚六一，陕西省西安市碑林区南院门街道钟楼社区治安指导员，2020 年获评 “全国先进工作者”，深耕社区治安一线 20 余年，以 “守一方平安、护邻里安宁” 为使命，为市中心核心区域治理注入硬核力量。​\n钟楼社区地处西安繁华地段，人流密集、商户集中，治安管理难度大。他创新构建 “民警 + 治安员 + 楼栋长 + 志愿者” 四级防控网，牵头组建 200 余人的 “红袖章” 巡逻队，每天带队开展 3 次重点区域巡查，年均排查安全隐患 400 余处，化解邻里纠纷、商户矛盾 180 余起，调解成功率达 98% 以上。针对社区老年居民多的特点，他推出 “平安守护” 专项行动，上门为独居老人安装紧急呼叫器，联合辖区单位开展防诈骗、防火灾宣传 30 余场，惠及居民 2000 余人次。​\n疫情防控期间，他连续 60 余天驻守社区，负责封控区值守、物资配送与秩序维护，牵头制定的 “分区管控、错峰出入” 方案在街道推广；日常工作中，他建立 “治安问题台账”，对电动车乱停放、商户消防隐患等问题实行 “销号管理”，推动社区连续 12 年无重大治安案件、无安全事故。他的实干赢得居民信赖，“有事找姚指导” 成为社区共识，其事迹先后被《西安日报》等媒体报道，用坚守诠释了基层工作者的责任与担当。",
