        "summary": "张小蔚，陕西省西安市碑林区张家村街道干部，2025 年获评 “全国先进工作者”，扎根基层治理一线 15 年，以 “把群众事当自家事” 的初心，为老城区街道治理交出民生答卷。​\n张家村街道涵盖 12 个社区，老旧小区占比超 70%，人口老龄化、基础设施薄弱等问题突出。她创新推行 “党建引领 + 网格赋能 + 多元共治” 工作模式，将街道划分为 89 个基础网格，联动党员、楼栋长、志愿者组建 “微治理小分队”，实现 “小事网格解、大事街道办”。针对老旧小区改造这一民生重点，她牵头成立专项工作组，逐户走访征求意见，累计推动 18 个老旧小区完成屋面防水、管网更新、加装电梯等改造项目，解决 2300 余户居民 “住房难” 问题，其中 3 个小区获评 “碑林区老旧小区改造示范项目”。\n在民生服务领域，她聚焦 “一老一小” 需求，推动建成街道综合养老服务中心，提供助餐、助浴、健康监测等服务，惠及辖区 800 余名老人；协调辖区学校、企业打造 “四点半课堂”，解决 200 余名双职工家庭子女托管难题。面对群众矛盾纠纷，她牵头成立 “小蔚调解室”，用 “唠家常式沟通 + 法理情融合” 的方式，年均化解邻里矛盾、物业纠纷 200 余起，调解成功率达 99%，“有纠纷找小蔚” 成为居民共识。​\n疫情防控、创文巩卫等重点工作中，她始终冲在一线，连续 30 余天驻守街道统筹调度，推动辖区实现 “零扩散”；组织开展环境整治行动 200 余次，清理卫生死角 120 余处，让老街道焕发新面貌。她先后荣获 “西安市优秀基层干部”“碑林区民生工作先进个人” 等称号，其主导的 “老旧小区改造群众参与机制” 在全市推广，用实干诠释了基层工作者的责任与温度。",
