        "name": "21陕西省西安市新城区长乐中路街道东尚社区原社区党委书记、居委会主任－刘丹－全国优秀城乡社区工作者",
        "summary": "刘丹，陕西省西安市新城区长乐中路街道东尚社区原社区党委书记、居委会主任，2022 年获评 “全国优秀城乡社区工作者”，扎根社区治理一线 12 年，以 “居民需求为导向、服务精准为目标” 的工作理念，为城市社区治理打造 “东尚样板”。​\n东尚社区涵盖 4 个商品房小区、1.2 万余名居民，兼具年轻家庭多、便民需求杂、治理精细化要求高的特点。她创新构建 “党建引领 + 网格赋能 + 居民自治” 的 “135” 工作模式：以 1 个社区党委为核心，组建党员先锋队、居民议事会、专业服务队 3 支队伍，推出养老助困、托育托管、矛盾调解、文化惠民、便民代办 5 项精准服务，将社区划分为 12 个网格、48 个微网格，实现 “小事不出网格、大事合力解决”。​\n针对社区 “一老一小” 核心需求，她牵头建成 200 平方米社区养老服务站，联合辖区医疗机构开展每月健康义诊，提供助餐、助洁、心理慰藉等服务，惠及 60 岁以上老人 300 余人；协调社区空间打造 “四点半课堂”，联动大学生志愿者提供作业辅导、兴趣培养，解决 120 余户双职工家庭子女托管难题。面对邻里纠纷与物业矛盾，她搭建 “东尚议事厅”，推行 “居民提、大家议、共同办” 机制，年均化解装修扰民、停车纠纷等问题 150 余起，调解成功率达 98%，“有事找刘书记” 成为居民口头禅。​\n疫情防控期间，她连续 40 余天驻守社区，统筹 300 余名志愿者开展物资配送、核酸检测组织工作，为独居老人、特殊群体建立 “一对一” 帮扶台账；创文巩卫工作中，她带头整治小区环境，推动增设非机动车停车区 12 处、分类垃圾桶站 30 个，组织文化活动 50 余场，让社区获评 “西安市文明社区”。她先后荣获 “西安市优秀社区党组织书记”“新城区民生工作先进个人” 等称号，其主导的 “居民议事会制度” 在新城区推广，用细致服务诠释了城乡社区工作者的责任与担当。",
