        "name": "22陕西省西安市新城区中山门街道万达社区党委书记、居委会主任－武峰－全国优秀城乡社区工作者",
        "summary": "武峰，陕西省西安市新城区中山门街道万达社区党委书记、居委会主任，2022年获评 “全国优秀城乡社区工作者”，深耕社区治理 10 年，以 “商居融合、共建共享” 为核心思路，破解商住混合社区治理难题，打造 “万达治理样板”。​\n万达社区涵盖 1 座商业综合体、5 个居民小区，聚集 1.5 万余名居民、200 余家商户及 3000 余名企业员工，兼具 “居民生活刚需 + 商户经营需求 + 流动人口服务” 三重治理属性。针对这一特点，武峰创新构建 “1+3+N” 商居联动治理模式：以 1 个社区党委为核心，组建 “党员攻坚队、商户联盟、志愿先锋队”3 支骨干队伍，联动市场监管、物业、商超等 N 方力量，建立 “商居议事会” 月度会商机制，打通居民与商户、企业间的沟通壁垒。​\n在民生服务领域，他聚焦 “居民便利 + 商户发展” 双需求：牵头建成 “万达商居服务站”，整合政务代办、健康义诊、法律咨询等服务，为居民提供 “家门口办事” 便利，为商户员工开通 “就近参保”“子女托管” 绿色通道；针对 “一老一小” 痛点，联合商场餐饮区推出 “老年助餐优惠”，协调社区空间打造 “托管驿站”，解决 80 余名双职工家庭子女及商户员工子女托管难题，惠及辖区 60 岁以上老人 400 余人。​\n面对商住矛盾焦点，他搭建 “武峰调解工作室”，创新 “商户公约 + 居民议事” 双轨调解法：针对商户噪音、油烟扰民等问题，组织商户签订《文明经营承诺书》，联合居民代表制定 “经营时段管控细则”；年均化解物业收费、邻里纠纷、商居矛盾 200 余起，调解成功率达 99%，其中 “商场促销噪声治理” 案例获评西安市 “优秀调解案例”。​\n疫情防控期间，他牵头成立 “商居防疫联盟”，统筹商户物资储备、志愿者力量，实现 “居民生活保供 + 商户有序复工” 双保障，为 120 余家民生类商户办理 “闭环经营证明”；在创文巩卫工作中，他推动 “文明商户” 评选，联合商户整治商圈环境，增设非机动车停放区 15 处、分类垃圾站 40 个，组织 “商居文化节” 30 余场，让社区获评 “西安市商居共治示范社区”。​\n他先后荣获 “西安市优秀社区党组织书记”“新城区基层治理先进个人” 等称号，主导的 “商居联动治理机制” 在新城区推广，用精准服务架起商居 “连心桥”，诠释了城乡社区工作者的责任与智慧。",
