        "name": "2陕西省安康市汉江志愿者救生队队长－周云康－全国道德模范",
        "summary": "周云康，男，汉族，非党，汉滨区政协委员，1961年10月生，安康市天星商贸公司总经理、安康市汉江志愿者救生队队长。2021年7月19日至21日，河南省新乡市暴雨成灾。周云康第一时间自发组织起救援队，跨省跨区域参加水上救援。7月23日凌晨，周云康带领救援队到达河南省新乡市凤泉区耿黄镇南鲁堡村，立即投入营救南鲁堡村被困的100多名村民。经过半个多小时的搜寻，周云康和队员救出6名村民。在救援中，经过一个彩印厂，先后将10名女职工和8名男职工救出，转移到安全地带。周云康和队员们连续奋战30多个小时，先后救援11次，救出64人。在被救群众中，年龄最大的81岁，最小的7岁，救援队的英雄举动，受到了当地党委、政府的高度评价和群众的好评。中国法制报、中新网、西部法制报等多家媒体报道了救援事迹。\n周云康在汉江中曾救过多名遇险群众，2016年7月组织成立志愿者救生队，以弘扬“奉献、友爱、互助、进步”的志愿精神，领导队员开展救援84次，救起溺水者92人，受到社会各界的广泛赞誉和好评，成为安康精神文明建设和见义勇为的一面旗帜，被群众誉称为“汉江生命的守护神”。\n周云康先后荣获最美汉滨人、安康好人、陕西好人、中国好人，安康市道德模范、第六届全国道德模范提名奖等荣誉，2019年12月被陕西省人民政府授予“陕西省第四届见义勇为英雄”称号。\n7月17日，第十四届全国见义勇为英模表彰大会在北京召开，我市汉江志愿者救生队队长周云康被中央政法委授予“第十四届全国见义勇为模范”称号。",
