        "name": "3陕西省安康市旬阳市桐木镇人民政府平安法治办主任、镇调委会副主任－黄家华－全国模范人民调解员",
        "summary": "黄家华，男，汉族，1967年1月出生，中共党员，大专文化，2014年3月从事司法行政工作，现任旬阳市桐木镇平安法治办主任、镇调委会副主任。所在镇2016年、2017年、2018年分别被旬阳县委、县政府表彰为平安建设工作先进镇、平安建设工作先进集体、“法治示范镇”。所在单位2018年被安康市司法局表彰为“全市优秀人民调解委员会”、被旬阳县委政法委表彰为“人民满意政法单位”。他本人也多次受到表彰奖励，2017年被旬阳县委、县政府授予“优秀人民调解员”荣誉称号，2018年被旬阳县委、县政府授予“平安建设工作先进个人”荣誉称号，2019年12月被安康市授予“金牌调解员”荣誉称号，2020年12月被司法部授予“全国模范人民调解员”荣誉称号，2021年6月被安康市委授予优秀共产党员荣誉称号。\n他从事调解工作十年以来，调解了多起疑难纠纷和信访积案，主持调解各类矛盾纠纷1450余件。提供司法援助12起，为群众挽回经济损失456.34万元。十年来累计接访群众870余人次，现场能够用法律法规、政策答复的当时就给来访者一个满意的答复，需要解决的问题及时解决，从不拖延，接访化解率100%，满意率98.8%。他调解方式很多，现场调解、微信调解、电话调解、抖音调解等等，只要能够利用上的调解资源他都会不失时机地使用上，尽量为当事人节约时间、节约成本。在任桐木镇调委会副主任以来，热情接待，细心倾听，认真分析，始终抱着“决不能让矛盾激化，更不能让民事纠纷转为刑事案件”的信念，认真开展矛盾纠纷调处工作。以法律为准绳，因人施教，晓之以理，动之以情，使得事情的解决合法、合理、合情。爱岗敬业，办事公道正派，廉洁自律，热心人民调解工作，始终坚持群众的事就是自己的事，群众的事就是大事，群众的事就必须要解决。",
