        "name": "8陕西省铜川市耀州区解放社区党总支书记－杨莎－全国优秀城乡社区工作者",
        "summary": "杨莎，女，1985年11月出生，中共党员，本科学历。2021年1月担任解放社区党总支书记。2022年11月被民政部评为全国优秀城乡社区工作者；2023年10月被陕西省司法厅评为全省优秀人民调解员。解放社区先后荣获全国模范人民调解委员会、中华全国归国华侨联合会侨胞之家、全国无邪教创建示范社区、全国侨联系统“侨胞之家”（2023-2024年度）典型选树单位、全省先进基层党组织、省级民主法治示范社区、陕西省慈善示范社区、全省标准化调委会、铜川市巾帼文明岗等荣誉称号。该同志党性信念坚定、工作踏实、敢于吃苦、乐于奉献，勇于创新，时刻以“情系老百姓，心暖千万家”为座右铭，真抓实干，砥砺前行。",
