        "summary": "马兰，女，1986年1月出生，中共党员，大专学历，现任青海省西宁市南滩街道建新社区党委书记、居委会主任。她扎根多民族群众混居社区14年，面对复杂的诉求与矛盾，她始终怀揣一颗“为民服务”的赤诚之心，在“走街串巷”中串起各族群众的情感线，在“办实事中”构筑起民族团结进步同心圆，社区各族群众就像石榴籽一样紧紧抱在一起。先后被民政部评为“全国优秀城乡社区工作者”；被国家卫生健康委员会、中国红十字总会、中央军委后勤保障部卫生局评为“2020—2021年度全国无偿献血志愿服务奖三星级”。",
