        "summary": "张丽，女，汉族，1979年6月出生，北京市人，2015年11月加入中国共产党，2012年5月参加工作，大学学历。今年，是张丽同志担任二号桥街陶然庭苑社区党委书记、居委会主任，也是从事党务工作的第8个年头，面对曾经二号桥地区矛盾复杂突出的小区，她从提升社区党组织力入手，从提升基层党建业务水平干起，从社区最硬的骨头啃起，拆除地上违法建设199处，房上房23处，解散原业委会，驱逐违规物业，选出红色业委会，引进新的物业公司，打造社区“一核多元”治理机制，全面落实网格化管理，积极探索智慧型社区建设，使陶然庭苑社区在党建引领下，实现了旧貌换新颜。",
