        "summary": "刘丽，女，41岁，中共党员，现任天津市津南区双新街道万盈家园社区党总支书记、居委会主任，天津市人大代表。十年来，她扎根基层，担任欣盛家园和万盈家园社区书记期间，探索出“六融三在”“盈盈为民”两大工作品牌，破解不同社区治理难题。她先后获评“全国优秀城乡社区工作者”“天津市劳动模范”“津南区美丽社工”等荣誉，她始终以党总支书记的基层治理主心骨角色、人大代表的民意桥梁身份，在两个特色社区的深耕实践中，将双重职责融入社区治理肌理，书写着新时代基层工作者“民有所呼、我必有应”的使命答卷。",
