        "summary": "李秋萍，女，汉族，1958年11月生，天津宁河人，2000年起参加志愿服务活动，所在志愿服务组织为天津市宁河区秋萍志愿服务中心，主要参加的服务项目包括扶贫助困、敬老助残、捐资助学、义务理发、文明实践、环境整治等十多个公益项目，累计参加志愿服务时数1.5万余小时（其中志愿天津系统时长3024小时）。\n李秋萍同志投身于志愿服务事业以来，成立了秋萍巾帼志愿服务队，逐步壮大为天津市宁河区秋萍志愿服务中心，队伍规模已发展到上千人，涉及爱心理发、扶贫助困、敬老助残等10余个公益领域，在“温暖津城·与爱同行”2024天津市互联网公益行动中，荣获2024天津市优秀公益品牌，个人先后荣获全国第八批岗位学雷锋标兵、全国三八红旗手、第十届全国五好文明家庭、天津市第七届道德模范提名奖、天津市首届志愿助残阳光使者、天津市最美妇联人、天津市优秀志愿者、天津市最美自强人等20多项国家级和市级荣誉称号。",
