        "name": "15天津市武清区东蒲洼街道蒲瑞馨园西社区调解员－沙乃臻－全国模范人民调解员",
        "summary": "沙乃臻，武清区司法局退休干部，现为武清区东蒲洼街道蒲瑞馨园西社区调委会专职调解员。曾获武清区“优秀共产党员”、天津市“优秀普法先进个人”、天津市“优秀人民调解员”、天津市“优秀离退休干部先进个人”等荣誉称号。从事社区调解工作10年多，他用最朴实的行动、用最真诚的心，赢得了群众的口碑和信任。近日，沙乃臻被司法部授予“全国模范人民调解员”荣誉称号。\n年近七旬的他，曾任职公职律师、司法局宣教科科长等，2013年临近退休投身社区调解，2016年推动成立武清区首家以调解员命名的“老沙调解工作室”。面对撤村建居后居民习惯转变引发的物业费、邻里噪音等纠纷，他凭公平公正与丰富阅历化解矛盾。\n他调解善融“法、理、情”，每日更新法律知识，讲法明晰；还会疏导群众情绪，解邻里心结。曾帮丧母的大学生小王联系父亲，促成其父每月支付生活费至她毕业；也曾劝诫乱倒脏物的餐馆老板，使其主动疏通管道并承诺整改。\n他爱好器乐与书画，视调解纠纷为奏和谐乐章、绘美好图景，以对群众的亲情与真情，坚守基层调解一线，彰显“枫桥经验”在津城的实践力量。",
