        "summary": "林则银，女，布依族，贵州都匀人，1974年2月出生，2010年6月入党，大学学历，社会工作师。现任北辰区瑞景街道宝翠花都社区党委书记、居委会主任、瑞景街道四级调研员，党的二十大代表、中国共产党天津市第十二届委员会候补委员、天津市妇联兼职副主席、市第十二次党代会代表、市第十八届人民代表大会社会建设委员会委员。从贵州大山来到海河之滨，她以社区为家，甘当社区的“女儿”，用心用情为居民服务，被誉为“社区天使”。作为“两优一先”代表，林则银同志在北京人民大会堂参加了庆祝中国共产党成立100周年“七一勋章”颁授仪式，受到习近平总书记的亲切会见，并在天安门广场参加庆祝中国共产党成立100周年大会观礼活动。本人先后荣获全国抗击新冠肺炎疫情先进个人、全国三八红旗手、全国优秀共产党员、全国诚信之星、天津楷模等荣誉。",
