      //   "summary": "作为社区书记，高彩霞带领社区工作人员和志愿者积极投身于一线防控工作，吃住在社区，用自己肩上的责任为居民筑起防疫的第一道屏障。一是发挥好在职党员及直管党员“双报到、双服务”作用。在疫情期间组织320名党员，进行拉网式的排查，防控信息统计、入户登记、配送物资、协调工作、安抚群众等工作，党员志愿者们+社区工作者+机关工作人员，强强联手防控疫情。二是创新防疫方法，做好隔离人员服务。南华社区有3011户7852人，共有398人进行居家隔离，社区工作人员少，居民需求量大，最多一天能走4万多步，而被隔离的居民对社区每天的走访多少又有些抵触情绪。看到这一情况高彩霞自创“硬核”又暖心的“隔门喊话”“视频报备”等方式，隔门对社区居民的生活轨迹以及健康状况进行排查和管控。一天三次走访、四次视频，叮嘱在家隔离的注意事项，既温暖民心又防止二代传染，得到了居民的肯定。三是多措并举做好疫情防控宣传。为了让居民更好地做好疫情防控，理解疫情防控工作，高彩霞觉得一定要做好宣传解释工作。前期组织社区有书法、绘画特长的党员创作疫情防控宣传标语和宣传画二百余幅，创作防疫“打油诗”鼓舞人心。后期通过举办“亭院里的小讲堂”“爱在庭院·520表白吧”等活动宣讲党的好政策、传播党的好思想、聆听党的好声音，做好疫情防控常态化宣传工作。",
