        "summary": "南环社区管辖12个老旧小区和1个县城内最大的集贸市场，有住户5428户1.08万余人，其中8个为无物业小区，面对困难，赵敬如将热情、智慧和心血全部融入工作中，把居民当家人，把人民群众满不满意当成自己工作唯一的标杆，社区先后荣获全国民族团结进步创建示范社区、全国综合减灾示范社区等荣誉，被评为五星级基层党组织和五星级和谐社区。本人先后荣获全国优秀城乡社区工作者、自治区民族团结进步模范个人、全区青少年普法教育工作表现突出工作者、银川市优秀共产党员、银川市最美社区书记等荣誉称号。",
