        "summary": "高冠茹同志，女，1981年10月出生，中共党员，本科学历，社会工作师，现任文化巷社区党委书记、主任职务。2009年5月参加社区工作，先后在火车站社区、文化巷社区工作，2010年5月任现职。她始终坚守理想信念、始终牢记初心使命，以高度的政治自觉、思想自觉和行动自觉，积极团结带领文化巷社区“两委”班子和党员干部常年扎根基层社区，全力以赴投入社区治理、服务居民的各项工作中，她用一颗赤胆忠心诠释了一名共产党员的政治本色，用一片赤诚情怀服务和温暖了一方群众，以良好的作风赢得了老百姓的赞誉。她探索出“凝聚微力量、提供微服务、实施微行动、开展微教育、实现微协商”的“五微”治理法，打造“五彩文化巷幸福社区”党建服务品牌。所在的社区先后获得固原市志愿服务先进集体、自治区第三届志愿服务项目三等奖、自治区先进基层党组织、全国妇联系统先进集体等荣誉。为更好地服务辖区居民群众，她积极倡导建立了居民微信群，及时宣传党和国家的各项惠民政策；最让她牵挂的还是辖区215户困难户、385名残疾人和112名重度残疾人的生活。16年间，她积极争取资源共慰问辖区困难群众1311户，发放慰问金9.5万元，慰问物资价值13.8万元；为住房困难居民解决住房420套；组织“联合党委”开展公益活动42次，为950名失业妇女和残疾人创办技能培训班21期，制作手工作品12000余件；迎新年文艺晚会暨“雷锋饺子宴”活动从2014年至今举办了十一届，深得3500多名老人的一致好评。\n在多年的服务群众实践中，高冠茹同志勇于探索、积极工作，2016年在固原市首先开设了“儿童之家”，开办了“七彩阳光”公益活动和“四点半课堂”，截至目前已有2100名困境儿童受益。她组织成立了“文化巷社区服务队”，发扬雷锋精神，积极参与辖区治安巡逻、环境保洁、结对帮扶、家政服务、文体宣传、义诊服务、政策法规宣传等服务活动，志愿服务队常年活跃于社区的大街小巷，成为和谐社区创建的一道亮丽的风景线。\n16年来，高冠茹同志初心如磐、矢志不渝，始终用心坚守着共产党员的初心使命，始终用心诠释着共产党员的初心使命。",
