      //   "summary": "2020年12月，王海燕同志获全国民政系统抗击新冠肺炎疫情优秀城乡社区工作者表彰。\n战“疫”先锋中，王海燕无悔坚守，点滴生活里，她可爱美好。她刚毅、坚强、细致、耐心，她是女儿、是母亲、是妻子，为了抗击疫情，她全身心地投入到抗疫第一线，谱写出了一曲铿锵战歌。从她给自己列出的一份份密密麻麻的抗疫工作清单上不难发现，那个春节长假，她可真是大忙人。处理湖北籍及其他疫情较重地区来石（返石）人员的跟进工作；辖区各居民小区登记对接汇总工作；特殊情况居民登记备案工作；辖区疫情统计数据收集汇总上报工作；防疫物资协调下发登记汇总工作；各类通知拟定、协调下发、张贴、宣传等公示工作；疫情期间辖区居民一户一档建档登记工作。为了完成这些工作，她一天也没有休息过。为了将防疫情况调查核实准确，她反复打电话跟居民一一核实。她将需要封闭的路口进行了统计，与社区下派单位的领导去拉材料，安装围挡需要用电，她立即去居民家里与居民沟通，解决了用电的问题，连夜与下派单位的人员一起对七处敞开的路口进行围挡。社区落实“四包一”工作以来，她除了坚守好自己的卡点，同时还负责与“四包一”下派的领导一起，对外省、市回来的人员进行严格的居家隔离工作。她每天要与医护人员为隔离人员测量体温，为隔离人员送生活用品，老旧小区没有天然气，她就为隔离人员家庭联系送煤气，同时为他们提供适时的心理疏导。她用自己的实际行动，为疫情防控工作贡献力量。",
