        "summary": "巴哈义古丽·尼合买提，女，塔塔尔族，1974年8月出生，中共党员，州级人大代表。在社区工作的20年中，巴哈义古丽·尼合买提从2000年至今因为认了汉族、回族、维吾尔族、哈萨克族等不同民族的13个“爸爸”“妈妈”，而被全县、全州、全区乃至国内外媒体熟知。她曾先后荣获全国“助老爱老敬老”模范、三八红旗手，自治区“最美新疆人”自治区第六届道德模范，昌吉州突出贡献优秀人才等60多项荣誉。",
