        "name": "5新疆维吾尔自治区乌鲁木齐市头屯河区中亚南路街道广州街社区党委书记－热先古力·托乎提－党的十九大代表、全国最美城乡社区工作者、全国民族团结进步模范个人",
        "summary": "热先古力・托乎提，女，维吾尔族，1964年3月出生，中共党员，长期在头屯河区中亚南路街道从事社区工作，是居民口中孤寡老人的“亲闺女”、流动人口子女的“热大妈”、群众的“好书记”与社区工作者的“领路人”；她给人干练朴实、风风火火的印象，十几年社区工作中业务刻苦、生活节俭、工作勤奋，以社区为家、以居民为重，凭扎实工作凝聚群众、团结群众。她十几年如一日早出晚归，坚持早晨学习以跟上时代，常以半个馒头、方便面充饥，忙时住守社区，2014年带领新成立的广州街社区当年就创成开发区（头屯河区）“五星级”社区（星级评选中无先例），到任该社区两个多月未休息、鞋底磨平，感冒发烧仍在社区挂点滴，即便丈夫抱怨“不图啥”，也始终因心中装满居民与社区事务而无悔舍小家。她一心为民，在卫星路社区时便照料低保户张金宝（腰椎双腿致残、母亲80岁体弱），且工作调动至中亚南路社区、广州街社区后仍未间断；抚养结亲对象刘妍去世后留下的8岁女儿，负责其家长会、学习与生活，多年来每月至少从工资中拿出500元帮助困难家庭（2018年超万元）；2013年得知低保户杜桂英女儿考上大学却凑不齐学费，先捐出“乌鲁木齐市优秀人才”2000元奖金，再动员11家企业设“圆梦基金”筹1.3万元补齐学费；2017年作为党的十九大代表，会后走街串巷宣讲党的十九大精神100余场，受益群众5万余人次。她不忘初心，信念扎根社区，曾获“全国学雷锋标兵”“自治区民族团结进步模范个人”“乌鲁木齐市优秀人才”“开发区优秀建设者”等荣誉，2010—2012年连续三年获评先进个人，2012年获“乌鲁木齐市创先争优优秀共产党员”，2017年当选党的十九大代表；她将奖金捐给瘫痪居民张建新、用于粉刷卫星路北二巷围墙并绘制民族团结内容，解决兴成花园小区绿化不足问题（种植苗木4000余株），协助烟草公司家属院等多个小区成立业主委员会，化解停车费、楼宇照明、电梯停运等难题；还带头成立“去极端化”宣讲队，一周内跑遍社区开展20多场宣讲覆盖2000余名居民，发声亮剑坚决反对“三股势力”与“两面人”，直言“要把群众小事当大事，带领大家创造美好生活”。正如她工作日志扉页所写：“面对艰难险阻无所畏惧，要把别人的困难当自己的困难，因为背后是群众期盼的眼神，我是社区党支部书记，就该是工作的领路人”，如今她仍以老党员、社区领路人、居民贴心人的身份，在社区默默奉献，用信念微光点燃希望。",
