        "summary": "焦振西，男，52岁，汉族，中共党员，现任新城街道八社区居委会副主任。自2002年从事社区工作以来，他始终以党建为引领，以“为民服务解难题”为工作宗旨，扎根社区一线，在安全生产、老旧小区改造、矛盾纠纷调解等工作中勇挑重担，用实干担当书写着新时代基层治理的暖心答卷，成为群众心中的“主心骨”和“贴心人”。2020年11月在由中国长安网，中央政法委长安剑主办开展的“平安之星”网络投票活动中荣获“平安之星”称号；2020年被评为“兵团安全生产先进个人”；2022年荣获“全国优秀城乡社区工作者”称号。",
