        "name": "0河北省秦皇岛市海港区天洋新城社区党委书记、居委会主任－周慧霞－全国优秀党务工作者、党的二十大代表、全国模范人民调解员、全国优秀城乡社区工作者",
        "summary": "周慧霞，河北省秦皇岛市海港区天洋新城社区党委书记、居委会主任，扎根基层24年，党的二十大代表，2021年“全国优秀党务工作者”获得者，获全国模范“小巷总理”等数十项荣誉。​\n她带领居民创新治理模式，建立“一领五协商”机制，以社区党委为轴心联动五方力量，设“六方公开栏”实现服务透明；打造智慧体系，研发社区治理平台整合居民数据，开发“智慧党建APP”激活“党员e生活”，推出“小润社区”小程序嵌入“一键呼叫”功能，构建“一刻钟便民圈”。\n民生服务中，推行“爱心代理儿女”制度，组织志愿者为65名空巢老人提供陪医、代购等服务，被称为“代理妈妈”；首创365天无假日办公。她带领居民用废弃建材建“幸福广场”，推动老旧小区改造，建成多项便民空间，她力推基层服务平台建设，用实干打通“最后一米”。​\n社区获国家及省市级荣誉60余项。",
