        "name": "1山西省怀仁市云东街道党工委副书记兼同仁路社区（原同仁家园社区）党委书记、居委会主任－吴志花－全国优秀党务工作者",
        "summary": "吴志花，女，1980年10月生，中共党员，在职研究生学历（山西省委党校政治学专业），2007年10月参加工作，现任怀仁市云东街道党工委副书记兼同仁路社区（原同仁家园社区）党委书记、居委会主任。\n2017年8月，她受组织选派，成为新成立的同仁家园社区首任党支部书记、居委会主任。作为社区工作新兵，她以党建为引领，践行总书记关于社区工作的指示，聚焦为民服务，深耕矿工家庭需求，带领社区从零起步逐步发展。\n在她的带领下，社区先后斩获“全省综合减灾示范社区”“山西省最美志愿服务社区”“2017-2020平安山西建设示范社区”等省市级以上荣誉；她个人也荣获“全国优秀党务工作者”“平安中国建设先进个人”“感动山西”十大人物、山西省“最美社区干部”等多项表彰，以真抓实干的“头雁”担当，为社区发展与民生服务注入强劲动力。",
