        "summary": "王洪亮，中共党员，阳城县凤城镇南关社区党委委员、人民调解委员会主任，2023年获司法部“全国模范人民调解员”称号，深耕调解一线13年，以自编《劝导书》和“用情感化、以德教化”理念化解纠纷，成功率超95%。\n他视调解为“崇高事业”，2021年3月，宁老太在张某超市坠亡引发赔偿争执，双方剑拔弩张欲激化冲突，他连夜请教法律专家，两天两夜居中调解，最终促成协议签订，避免群体事件。2020年，他历时三个月化解裘某与吕某20年房产过户纠纷，既向裘某讲“信义”之道，又为吕某普法析理，终让双方达成补偿协议，阻止极端事件发生。​\n他坚持勤学精进，自学《中华人民共和国民法典》等法规，参加省市级培训，总结案例提炼技巧，同时借调解契机普法，推动社区形成“遇事找法”氛围。累计化解婚姻家庭、经济赔偿等纠纷300余起，被群众称为“贴心人”，获“山西省二级人民调解员”等多项荣誉。​",
