        "name": "3山西省临汾市尧都区铁路东街道三元社区党委书记、居委会主任－刘卫星－全国优秀城乡社区工作者、全国三八红旗手",
        "summary": "刘卫星，女，1970年8月出生，中共党员，现任铁路东街道三元社区党委书记兼居委会主任，同时担任山西省第十四届人大代表等多个重要职务。\n自2002年4月起，刘卫星便担任三元社区党委书记兼居委会主任，至今已有近31年。工作中，她秉持“坚守初心、不辱使命、奋勇争先、甘于奉献”的新时代三元铁人精神，以党建为引领，强化党组织建设，凝聚党员力量，充分发挥党员先锋模范作用。在服务居民方面，她深入了解居民需求，创新服务形式，构建了全方位、多层次的社区服务体系。同时，她还善于盘活社区资源，实现资源的优化配置，为社区发展提供了坚实保障。\n在刘卫星的努力下，三元社区实现了华丽转身，从曾经的“老乱穷”社区变成了居民安居乐业的“幸福园”，居民的幸福指数、安全感和满意度大幅提升。\n她的工作也得到了广泛认可，先后荣获“全国优秀社区专职工作者”“全国三八红旗手”等众多荣誉称号，还曾两次在人民大会堂受到习近平总书记的亲切接见。刘卫星用实际行动诠释了一名优秀共产党员的初心与使命，是基层社区工作者学习的榜样。",
