        "summary": "宋金锋，1968年生，中共党员，孝义市崇文街道留义社区党支部书记、居委会主任，扎根基层20余年，获评“全国优秀城乡社区工作者”，还获“全国道德模范提名奖”“全国五一劳动奖章”等20余项省部级以上荣誉。\n他秉持“一人富不算富，大家富才算富”理念，2000年接任后，牵头推进城中村改造、集体产权制度改革，2017年完成“村改社区”，构建现代化产业体系，2022年股民人均分红及福利超1万元，实现“村民变市民、市民变股民”。\n他践行“群众事无小事”，成立“金锋工作室”，累计接待群众1200余人次，解决难题430余件；实施硬化、绿化等六项改造工程，推动廉租房办理、不动产权证办理等民生实事落地。​\n他注重“富口袋也富脑袋”，以亲孝文化为特色，2003年起评比好婆婆、好媳妇，每年办“孝亲敬老”活动，推行“居民新时代文明行为积分制度”，带动社区形成尊老爱幼、干群和谐的风气，带领社区获“全国民主法治示范社区”等称号。",
