        "summary": "张秀珍，山西省忻州市五台县居民办事处西米市社区党支部书记，忻州市人大代表，1975年入党，深耕基层四十余年，以实际行动践行共产党员初心使命。\n她是抗疫一线的“逆行者”。2020年疫情来袭，她冲锋在前，冒严寒奔走于16个小区间，妥善安置武汉返家人员并保障生活，甚至因紧急工作未能及时照料摔伤的老母亲。同年9月，她在人民大会堂获国务院“全国抗击新冠肺炎疫情先进个人”表彰。\n她是社区治理的“排头兵”。2013年退休后接管大型社区，创新推行“微网格”管理与“四单式”服务，建立矛盾调解委员会，实现“矛盾不出社区，服务不打烊”。累计处理群众诉求超500条，调解纠纷268次，帮扶残疾人、孤寡老人数万次，带动千余名党员群众参与治理。\n她是群众信赖的“贴心人”。坚持党建引领，以“党性最强、作风最正”原则自我要求，创办阳光服务中心、托养服务中心，助力150余名贫困户就业，资助56名孤儿至学业完成。2022年11月获民政部“全国优秀城乡社区工作者”称号，2023年2月获全国妇联“全国三八红旗手”称号，用数十年坚守诠释“全心全意为人民服务”的宗旨。",
