        "summary": "董殿英，女，中共党员，现任阳泉市城区上站街道市政府大院社区党委书记、居委会主任，同时担任全国青联委员等多项职务，拥有国家二级心理咨询师等专业资质。\n她探索建立“1234”工作体系，成立全市首家“党员党性体检中心”，壮大党建“朋友圈”。运用11431机制，让“学习强国”平台在社区热起来。成立城区首家以个人命名的“殿英”调解工作室，创新“4+1”调解法，已化解各类纠纷1800余件。\n董殿英还带领社区干部探索“查、清、拆、管、宣、美”六字工作法，构建“大城小院”特色社区。防疫期间，推行“5＋N＋X”工作模式，筑牢抗疫“防火墙”。她打造的“0353幸福列车”工作法成功入选2022年度全国社区治理十佳案例，搭建起“社区大党委－小区（网格）党支部－楼栋党小组－党员中心户”四级组织架构，推动社区治理水平不断提升。\n由于工作表现突出，她先后获得全国人民调解工作先进个人、第20届“山西青年五四奖章”、山西省优秀共产党员等多项荣誉，其工作多次被人民网、学习强国等媒体报道300余次。",
