        "summary": "郭志英，大连市西岗区八一路街道林茂社区党委书记、居委会主任。\n2002年，郭志英带着儿子随军来到大连，2005年，她以军嫂的身份投身社区工作，至今已有近20年基层社区工作经验。她始终坚守“我的手机24小时开机，我将24小时为您服务”的承诺，把家安在社区，全心全意为人民服务。\n在社区治理方面，她总结提炼出老旧小区治理“新十难”问题，搭建四级“小巷议事平台”，创新打造“小巷管家”社区托管型物业服务新模式，使社区治理触角延伸到街头巷尾。她还借助“郭志英劳模工作室”，带动众多榜样力量参与社区治理服务，先后与123户独居老人开展亮灯之约，为30余户残疾家庭送去温暖，解决40余处公共设施维修问题等，受益者达2000余人次。\n作为一名共产党员，她积极学习贯彻习近平新时代中国特色社会主义思想，培养了一批党课“银发”宣讲员，建大连市西岗区八一路街设立“小巷微课堂”，为党员提供线上线下学习服务，并在多个社区书记培训班进行宣讲。\n由于工作表现突出，她先后荣获全国食品安全工作先进个人、中国好人、辽宁省劳动模范等30余项荣誉称号。她用真心真情为群众排忧解难，用实际行动诠释了一名基层社区工作者的责任与担当，是居民心中当之无愧的“小巷总理”。",
