        "name": "6辽宁省沈阳市大东区津桥街道百乐社区党委书记－孔艳－全国抗击新冠肺炎疫情先进个人",
        "summary": "孔艳，现任沈阳市大东区津桥街道百乐社区党委书记、居委会主任，长期扎根基层，拥有丰富的社区治理经验，始终以扎实作风和为民宗旨开展工作，深得辖区居民认可。\n2020年疫情防控期间，她带领社区工作人员坚守一线，构建严密防控体系。每日凌晨4时许通过微信群掌握居民动态，8时开展常态化巡查，9时核实重点人员身体状况，中午向沿街店铺宣传防疫政策，14时组织小区消毒，傍晚解答居民疑问，夜间上门排查，深夜统计防疫信息。1月25日凌晨1时30分社区出现确诊病例后，她不惧风险上门为患者家属送生活用品、做心理疏导，获家属信任并受托保管家门钥匙。辖区首位治愈患者回家隔离时，因家人仍在治疗，她主动承担照顾责任，定期送生活用品，正月十五还特意送去汤圆与蛋糕。\n荣誉方面，2020年9月8日她受邀参加全国抗击新冠肺炎疫情表彰大会，获“全国抗击新冠肺炎疫情先进个人”称号，还曾获“大东区劳动模范”等荣誉。\n社区建设中，她在老旧小区改造时创新推行“人民设计师”理念，邀请辖区建筑专业背景的年轻人参与规划设计，结合居民需求与专业知识，让改造更贴合生活，为社区发展注入新活力。",
