        "name": "7辽宁省沈阳市和平区南湖街道文安路社区党委第一书记－胡静琴－全国优秀党务工作者",
        "summary": "胡静琴，女，汉族，1951年2月生，1972年6月入党，大专文化，现任沈阳市和平区南湖街道文安路社区胡静琴书记工作室主任兼社区党委第一书记。2001年从省直部门处级岗位退休后，扎根社区工作20余年，获“全国优秀党务工作者”“全国小巷总理之星”等70余项荣誉，2021年作为代表参加建党百年庆典。\n她创新基层党建，2006年推动“支部建在小区”，建22个小区党支部、14个“党群之家”，实现党组织全覆盖；创立全国首家社区业主代表协会、物业服务中心，破解弃管小区难题，组建千余人义工队伍，2014年打造沈阳首家社区居家养护中心。疫情期间，她60天住社区指挥，70岁时仍冒-20℃低温组织核酸检测，保障居民安全。\n2019年“胡静琴书记工作室”成立，提炼社区工作法，组建专家、“领头雁”等团队，举办培训班176期，培训28000余人次。在她带领下，文安路社区获“全国文明单位”“全国创先争优先进基层党组织”等称号，切实提升居民获得感、幸福感、安全感。",
