        "summary": "樊晨，省人大代表，现任吉林市昌邑区文庙街道天胜社区党委书记、居委会主任，2000年在社区“两委”换届中当选该社区党委书记，深耕基层治理多年。\n面对天胜社区“四多”治理难题，她通过召开居民议事会破解小区治理痛点，例如推动天胜二区环境改造，使其从“老大难”变为“新亮点”。工作中，她建立“清单制”目标，总结出“1235”“一站四化”等实用工作法；打造“红色引领示范带”、区域化党建服务中心、志愿服务教育基地，高效解决辖区居民各类急难愁盼问题。\n作为省人大代表，她切实发挥“传声筒”作用，牵头激活代表家站功能，打造居民家门口的人大联络站点，完善基层治理平台并建立民事纠纷调解机制。同时，创新推出“庭院议会”“百姓说事点”等议事协商品牌，牵头成立专项小组与志愿服务队，精准回应群众诉求，化解烦心事，夯实社区治理根基。",
