        "summary": "薛晓婉，女，1990年生，中共党员，现任吉林市丰满区红旗街道田园社区党总支书记、居委会主任，吉林市政协委员。2014年底，24岁的她经换届选举到田园社区任职，面对社区人员复杂、流动性强的难题，率先推行“全科社工”“全能网格”“全面服务”的“三全”工作模式，提升服务效能，带领社区获“百强党支部”“巾帼建功先进集体”。\n2016年田园小区物业弃管，她放弃休息组织调查选择新物业，3个月内解决顶楼漏水、规划停车位、安装监控、清楼道野广告等问题，让小区焕新。针对社区下岗职工和零就业家庭多的情况，她探索“技能培训+推荐就业+家政服务”全链条模式，助力失业人群再就业。\n2020年疫情期间，怀孕8个多月的她坚守一线排查消杀，因劳累失去孩子，休产假不到2个月便返岗。吉林疫情时，她和工作人员在社区吃住27天，日工作约20小时，将5岁女儿托付父母，落实商铺停业、单元封闭等措施，扩网格微信群发防控信息，“挂图作战”分组服务，日均走4万多步、减重10多公斤，2020年9月获评“全国抗击新冠肺炎疫情先进个人”。\n2022年2月她参与北京冬奥会开幕式国旗传递，2023年作为市身边榜样宣讲团成员，以《“90后”社区书记的青春力量》宣讲，号召干事创业。",
