        "summary": "华磊同志，女，1989年6月出生，中共党员，本科学历。2009年11月入伍担任“世博女兵”。退役后于2011年11月开始参加社区工作，先后在虹口区嘉兴路街道香港丽园居民区、瑞一居民区等工作。2013年5月至2016年3月，担任虹口区嘉兴路街道瑞一居民区党总支副书记；2016年3月至2024年12月，担任瑞一居民区党总支书记。她发动社区党员发挥正能量，利用互联网资源，开展微管理、微党课、微帮扶的“三微活动”。她支持建立“英语沙龙”“快乐老宝贝”“老伙伴计划”等十多个社区项目，让更多居民参与社区活动与社区治理，进一步增强社区党员群众的凝聚力和向心力。先后获得了“全国最美城乡社区工作者”“上海市五四青年奖章”等荣誉。",
