        "name": "11上海市闵行区虹桥镇西郊居民区党总支书记－高君锋－全国优秀城乡社区工作者",
        "summary": "高君锋，男，1982年10月生，中共党员，本科，现任闵行区虹桥镇西郊居委会党支部书记、主任。2003年12月入伍，2005年12月退伍，2014年4月参加社区工作，曾获上海市“五一劳动奖章”、全国优秀城乡社区工作者等荣誉，带领居委会获上海市垃圾分类百佳居委。​\n他聚焦居民需求，深耕加装电梯工作。虹桥西郊公寓是农民动迁小区，老年居民多，高层出行难。2018年，他得知90岁老党员爬六楼需20分钟，遂推动26号楼加梯，带领居委干部上门沟通3个月，实现100%签约，一楼业主专程从台湾返沪签约。​\n2021年，他推进小区66个门栋加梯征询，克服居民对方案、费用的忧虑，利用晚间和双休日召开32场协调会，确定统一建设单位与电梯品牌；对接银行设收款点，5天完成42个门栋，还成立20人“加梯监督小组”。目前小区47个楼栋逐步开工，13个已完工，形成“全市首个整体装配式施工加梯小区”“全区首个批量安全论证集中开工加梯小区”，形成“西郊模式”。​",
