        "summary": "朱国萍满怀对群众的热情，坚守“核心在支部，专心抓党员，热心办实事，真心换民心”准则与“群众利益无小事”信念，脚踏实地为居民服务，充分发挥基层党组织在地区性、社会性、群众性、公益性工作中的领导核心作用，推动居民区实现“自我教育、自我服务、自我管理”。\n为提升基层党组织服务能力，她注重机制、制度、方法创新：1998年总结《虹储居民区党支部工作法》，2005年又结合实践完善，提出“虹储居民区党总支先进性建设目标管理”及“保持共产党员先进性”工作制、“党建带团建”接班人培养制等七大管理制度，以制度规范工作、约束行为，让居民区服务更规范、细致、长效。\n2015年，在她积极争取下，全国人大常委会法工委在虹桥街道设立基层立法联系点（全国四家之一）。她借助该平台“上传”基层鲜活故事，助力法条精准聚焦民生痛点。\n2018年5月，朱国萍从深耕28年的社区岗位退休，随后创设萍聚工作室，组建含专业权威人士、基层实践楷模、民主自治领袖的核心团队，开展培训宣讲、咨询指导、公益招募、评估监督四类服务，并对接长三角，从更广阔视角探索基层治理。",
