        "name": "2上海市闵行区莘庄镇康城社区党委专职副书记－张军萍－党的二十大代表、第十四届全国政协委员",
        "summary": "张军萍，女，1977年12月生，汉族，上海人，大学学历，1998年6月入党，现任党的二十大代表、第十四届全国政协委员，莘庄镇康城社区党委专职副书记等职，市妇联兼职副主席，曾获全国优秀共产党员、抗击新冠肺炎疫情全国三八红旗手称号。​\n作为4万人社区的“大管家”，10年来她依托党建引领，探索超大型社区管理路径，带领党员干部群众改善社区“脏乱差”面貌，实现华丽蜕变。她深入群众，打造“莘智汇”公共空间，推动“美好社区合伙人”项目，凝聚专业力量以共商共议寻求治理“最大公约数”，践行全过程人民民主。\n针对维修项目积压问题，她推动智慧赋能，支持业委会研发“社区日常维修电子签核系统”，以“人”“屋”“事”清单解决群众“身边小事”；心系“一老一小”，推进日间照料中心、老年食堂建设，开展童议家园项目，助力打造人人有责、尽责、享有的社会治理共同体。",
