        "name": "6上海市浦东新区宣桥镇艺泰安邦第一居民区党总支书记－陈凤英－全国先进工作者",
        "summary": "陈凤英，女，1974年11月生，浦东新区人大代表，现任上海市浦东新区宣桥镇艺泰安邦第一居民区党总支书记。曾先后荣获全国先进工作者、上海市新时代居村好班长、上海市担当作为优秀居村党组织书记、上海市优秀党务工作者、上海市劳动模范、上海市“三八红旗手”、上海市优秀“三支一扶”带教老师、浦东新区先进工作者等荣誉称号。\n陈凤英坚持以党建为引领，秉持“不以事小而不为”的原则，结合多年来扎根基层的丰富经验，创建“邻”聚力劳模工作室和“邦帮”书记工作室，充分调动党员参与社会治理的积极性，做到“一名党员一面旗帜”，增强社区党组织的感召力、影响力和凝聚力；积极发挥传帮带作用，延伸“百事联”党群服务站和“邻聚里”党建品牌效应，创建“老法师”调解室，搭建共商共治的“园事桌”，组建艺泰墨缘书画睦邻点、邦邦合唱团、艺韵走秀队等多支社区文化服务团队，挖掘培养群众自治带头人，探索从机构管理到社区自治的解放模式。陈凤英提出了多个党建引领基层社区治理解题新思路，不断以更优质的服务、更便民的举措、更暖心的关怀服务社区居民，让小区居民真正安居乐业，努力打造“人人有责、人人尽责、人人享有”的大型居民区治理新格局。",
