        "summary": "何晓英，女，1980年1月生，中共党员，全国助理社工师，现任上海市金山区石化街道东礁新村第二居民区党总支副书记、居委会主任，2014年起投身社区工作，扎根8年，是居民眼中的“好干部”“贴心人”。​\n她常因牵挂社区失眠，年三十冒雨为独居老人送年夜饭，疫情期间坚守防疫一线，凌晨排查重点人员，牵头解决“美丽家园”建设、疫苗接种等民生事，呵护72位独居老人，节日问候从不缺席。她还帮独居老人魏师傅调解20多年矛盾，1个月内10余次努力，助其临终前与女儿相见。\n身为视力障碍者，何晓英任金山区残联盲协副主席5年，毫无怨言。她组织视障者技能培训，帮张伟开5家盲人按摩店，纳入培训课程助30多名盲人体面就业；鼓励韩星辰组建乐队实现音乐梦，成1.2万视障者的“眼睛”“拐杖”。她说：“被居民需要是最大幸福。”",
