        "name": "8上海市普陀区长寿路街道普雄路居民区党总支书记、居委会主任－张婧－全国优秀城乡社区工作者",
        "summary": "张婧，女，1982年10月生，中共党员，本科，现任普陀区长寿路街道普雄路居民区党总支书记、居委会主任，2011年3月入职该居民区，2016年8月任现职，曾获普陀区“最美书记”、上海市“网络好榜样”等多项荣誉。\n她深耕社区，成效显著。2020年疫情以来，整合“三驾马车”及志愿者力量，攻克口罩预约、返沪排摸等难题；2021年燕宁苑封楼时，一线统筹安抚居民、召回人员、核酸检测等工作，筑牢防疫堡垒。针对居民区2120户、5000余名居民（含近千老人、200余户弱势群体），她聚焦民生。普雄馨苑4幢高层因台阶阻碍特殊群体出行，她联系中船九院定制升降机方案，通过“三会”制度立项，获街道资金支持，2021年底升降机投用。​\n2016年，她接下街道“食物银行”试点任务，奔走洽谈稳定货源、制定规则。5年多来，志愿者从6人扩至近50人，受益近30万人次，项目获多方认可，接受领导视察以及多家媒体报道。​",
